INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,145,'Al-An''aam','قُل لَّآ أَجِدُ فِي مَآ أُوحِيَ إِلَيَّ مُحَرَّمًا عَلَىٰ طَاعِمࣲ يَطۡعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيۡتَةً أَوۡ دَمࣰ ا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِيرࣲ فَإِنَّهُۥ رِجۡسٌ أَوۡ فِسۡقًا أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغࣲ وَلَا عَادࣲ فَإِنَّ رَبَّكَ غَفُورࣱ رَّحِيمࣱ‏','کہو کہ جو احکام مجھ پر نازل ہوئے ہیں ان میں کوئی چیز جسے کھانے والا کھائے حرام نہیں پاتا بجز اس کے کہ وہ مرا ہوا جانور یا بہتا لہو یا سور کا گوشت کہ یہ سب ناپاک ہیں یا کوئی گناہ کی چیز ہو کہ اس پر خدا کے سوا کسی اور کا نام لیا گیا ہو اور اگر کوئی مجبور ہو جائے لیکن نہ تو نافرمانی کرے اور نہ حد سے باہر نکل جائے تو تمہارا پروردگار بخشنے والا مہربان ہے','Say, ˹O Prophet,˺ “I do not find in what has been revealed to me anything forbidden to eat except carrion, running blood, swine—which is impure—or a sinful offering in the name of any other than Allah. But if someone is compelled by necessity—neither driven by desire nor exceeding immediate need—then surely your Lord is All-Forgiving, Most Merciful.”','(ऐ रसूल) तुम कहो कि मै तो जो (क़ुरान) मेरे पास वही के तौर पर आया है उसमें कोई चीज़ किसी खाने वाले पर जो उसको खाए हराम नहीं पाता मगर जबकि वह मुर्दा या बहता हुआ ख़़ून या सूअर का गोश्त हो तो बेशक ये (चीजे) नापाक और हराम हैं या (वह जानवर) नाफरमानी का बाएस हो कि (वक्ते ़ज़िबहा) ख़ुदा के सिवा किसी और का नाम लिया गया हो फिर जो शख्स (हर तरह) बेबस हो जाए (और) नाफरमान व सरकश न हो और इस हालत में खाए तो अलबत्ता तुम्हारा परवरदिगार बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,146,'Al-An''aam','وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرࣲۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمࣲۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ','اور یہودیوں پر ہم نے سب ناخن والے جانور حرام کر دئیے تھے اور گایوں اور بکریوں سے ان کی چربی حرام کر دی تھی سوا اس کے جو ان کی پیٹھ پر لگی ہو یا اوجھڑی میں ہو یا ہڈی میں ملی ہو یہ سزا ہم نے ان کو ان کی شرارت کے سبب دی تھی اور ہم تو سچ کہنے والے ہیں','For those who are Jewish, We forbade every animal with undivided hoofs and the fat of oxen and sheep except what is joined to their backs or intestines or mixed with bone. In this way We rewarded them for their violations. And We are certainly truthful','और हमने यहूदियों पर तमाम नाख़ूनदार जानवर हराम कर दिये थे और गाय और बकरी दोनों की चरबियां भी उन पर हराम कर दी थी मगर जो चरबी उनकी दोनों पीठ या आतों पर लगी हो या हडड्ी से मिली हुई हो (वह हलाल थी) ये हमने उन्हें उनकी सरक़शी की सज़ा दी थी और उसमें तो शक ही नहीं कि हम ज़रूर सच्चे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,147,'Al-An''aam','فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةࣲ وَٰسِعَةࣲ وَلَا يُرَدُّ بَأۡسُهُۥ عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِينَ','اور اگر یوں لوگ تمہاری تکذیب کریں تو کہہ دو تمہارا پروردگار صاحب رحمت وسیع ہے مگر اس کا عذاب گنہ گاروں لوگوں سے نہیں ٹلے گا','But if they deny you ˹O Prophet˺, say, “Your Lord is infinite in mercy, yet His punishment will not be averted from the wicked people.”','(ऐ रसूल) पर अगर वह तुम्हें झुठलाएं तो तुम (जवाब) में कहो कि (अगरचे) तुम्हारा परवरदिगार बड़ी वसीह रहमत वाला है मगर उसका अज़ाब गुनाहगार लोगों से टलता भी नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,148,'Al-An''aam','سَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءࣲۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُواْ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمࣲ فَتُخۡرِجُوهُ لَنَآۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ','جو لوگ شرک کرتے ہیں وہ کہیں گے کہ اگر خدا چاہتا تو ہم شرک نہ کرتے اور نہ ہمارے باپ دادا (شرک کرتے) اور نہ ہم کسی چیز کو حرام ٹھہراتے اسی طرح ان لوگوں نے تکذیب کی تھی جو ان سے پہلے تھے یہاں تک کہ ہمارے عذاب کا مزہ چکھ کر رہے کہہ دو کیا تمہارے پاس کوئی سند ہے (اگر ہے) تو اسے ہمارے سامنے نکالو تم محض خیال کے پیچھے چلتے اور اٹکل کی تیر چلاتے ہو','The polytheists will argue, “Had it been Allah’s Will, neither we nor our forefathers would have associated others with Him ˹in worship˺ or made anything unlawful.” Likewise, those before them rejected the truth until they tasted Our punishment. Ask ˹them, O Prophet˺, “Do you have any knowledge that you can produce for us? Surely you follow nothing but ˹false˺ assumptions and you do nothing but lie.”','अनक़रीब मुशरेकीन कहेंगें कि अगर ख़ुदा चाहता तो न हम लोग शिर्क करते और न हमारे बाप दादा और न हम कोई चीज़ अपने ऊपर हराम करते उसी तरह (बातें बना बना के) जो लोग उनसे पहले हो गुज़रे हैं (पैग़म्बरों को) झुठलाते रहे यहाँ तक कि उन लोगों ने हमारे अज़ाब (के मज़े)े को चख़ा (ऐ रसूल) तुम कहो कि तुम्हारे पास कोई दलील है (अगर है) तो हमारे (दिखाने के) वास्ते उसको निकालो (दलील तो क्या) पेश करोगे तुम लोग तो सिर्फ अपने ख्याल ख़ाम की पैरवी करते हो और सिर्फ अटकल पच्चू बातें करते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,149,'Al-An''aam','قُلۡ فَلِلَّهِ ٱلۡحُجَّةُ ٱلۡبَٰلِغَةُۖ فَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ','کہہ دو کہ خدا ہی کی حجت غالب ہے اگر وہ چاہتا تو تم سب کو ہدایت دے دیتا','Say, “Allah has the most conclusive argument. Had it been His Will, He would have easily imposed guidance upon all of you.”','(ऐ रसूल) तुम कहो कि (अब तुम्हारे पास कोई दलील नहीं है) ख़ुदा तक पहुंचाने वाली दलील ख़ुदा ही के लिए ख़ास है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,150,'Al-An''aam','قُلۡ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشۡهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَاۖ فَإِن شَهِدُواْ فَلَا تَشۡهَدۡ مَعَهُمۡۚ وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَهُم بِرَبِّهِمۡ يَعۡدِلُونَ','کہو کہ اپنے گواہوں کو لاؤ جو بتائیں کہ خدا نے یہ چیزیں حرام کی ہیں پھر اگر وہ (آ کر) گواہی دیں تو تم ان کے ساتھ گواہی نہ دینا اور نہ ان لوگوں کی خواہشوں کی پیروی کرنا جو ہماری آیتوں کو جھٹلاتے ہیں اور آخرت پر ایمان نہیں لاتے اور (بتوں کو) اپنے پروردگار کے برابر ٹھہراتے ہیں','Say, ˹O Prophet,˺ “Bring your witnesses who can testify that Allah has forbidden this.” If they ˹falsely˺ testify, do not testify with them. And do not follow the desires of those who deny Our proofs, disbelieve in the Hereafter, and set up equals with their Lord','फिर अगर वही चाहता तो तुम सबकी हिदायत करता (ऐ रसूल) तुम कह दो कि ( अच्छा) अपने गवाहों को लाकर हाज़िर करो जो ये गवाही दें कि ये चीज़े (जिन्हें तुम हराम मानते हो) खुदा ही ने हराम कर दी हैं फिर अगर (बिलग़रज़) वह गवाही दे भी दे तो (ऐ रसूल) कहीं तुम उनके साथ गवाही न देना और जिन लोगों ने हमारी आयतों को झुठलाया और आख़िरत पर ईमान नहीं लाते और दूसरों को अपने परवरदिगार का हम सर बनाते है उनकी नफ़सियानी ख्वाहिशों पर न चलना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,151,'Al-An''aam','۞قُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـࣰٔ اۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنࣰ اۖ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ إِمۡلَٰقࣲ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ وَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ','کہہ کہ (لوگو) آؤ میں تمہیں وہ چیزیں پڑھ کر سناؤں جو تمہارے پروردگار نے تم پر حرام کر دی ہیں (ان کی نسبت اس نے اس طرح ارشاد فرمایا ہے) کہ کسی چیز کو خدا کا شریک نہ بنانا اور ماں باپ (سے بدسلوکی نہ کرنا بلکہ) سلوک کرتے رہنا اور ناداری (کے اندیشے) سے اپنی اولاد کو قتل نہ کرنا کیونکہ تم کو اور ان کو ہم ہی رزق دیتے ہیں اور بےحیائی کے کام ظاہر ہوں یا پوشیدہ ان کے پاس نہ پھٹکنا اور کسی جان (والے) کو جس کے قتل کو خدا نے حرام کر دیا ہے قتل نہ کرنا مگر جائز طور پر (یعنی جس کا شریعت حکم دے) ان باتوں کا وہ تمہیں ارشاد فرماتا ہے تاکہ تم سمجھو','Say, ˹O Prophet,˺ “Come! Let me recite to you what your Lord has forbidden to you: do not associate others with Him ˹in worship˺. ˹Do not fail to˺ honour your parents. Do not kill your children for fear of poverty. We provide for you and for them. Do not come near indecencies, openly or secretly. Do not take a ˹human˺ life—made sacred by Allah—except with ˹legal˺ right. This is what He has commanded you, so perhaps you will understand','(ऐ रसूल) तुम उनसे कहो कि (बेबस) आओ जो चीज़ें ख़ुदा ने तुम पर हराम की हैं वह मैं तुम्हें पढ़ कर सुनाऊँ (वह) यह कि किसी चीज़ को ख़ुदा का शरीक़ न बनाओ और माँ बाप के साथ नेक सुलूक़ करो और मुफ़लिसी के ख़ौफ से अपनी औलाद को मार न डालना (क्योंकि) उनको और तुमको रिज़क देने वाले तो हम हैं और बदकारियों के क़रीब भी न जाओ ख्वाह (चाहे) वह ज़ाहिर हो या पोशीदा और किसी जान वाले को जिस के क़त्ल को ख़ुदा ने हराम किया है न मार डालना मगर (किसी) हक़ के ऐवज़ में वह बातें हैं जिनका ख़ुदा ने तुम्हें हुक्म दिया है ताकि तुम लोग समझो और यतीम के माल के करीब भी न जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,152,'Al-An''aam','وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ','اور یتیم کے مال کے پاس بھی نہ جانا مگر ایسے طریق سے کہ بہت ہی پسندیدہ ہو یہاں تک کہ وہ جوانی کو پہنچ جائے اور ناپ تول انصاف کے ساتھ پوری پوری کیا کرو ہم کسی کو تکلیف نہیں دیتے مگر اس کی طاقت کے مطابق اور جب (کسی کی نسبت) کوئی بات کہو تو انصاف سے کہو گو وہ (تمہارا) رشتہ دار ہی ہو اور خدا کے عہد کو پورا کرو ان باتوں کا خدا تمہیں حکم دیتا ہے تاکہ تم نصحیت کرو','And do not come near the wealth of the orphan—unless intending to enhance it—until they attain maturity. Give full measure and weigh with justice. We never require of any soul more than what it can afford. Whenever you speak, maintain justice—even regarding a close relative. And fulfil your covenant with Allah. This is what He has commanded you, so perhaps you will be mindful','लेकिन इस तरीके पर कि (उसके हक़ में) बेहतर हो यहाँ तक कि वह अपनी जवानी की हद को पहुंच जाए और इन्साफ के साथ नाप और तौल पूरी किया करो हम किसी शख्स को उसकी ताक़त से बढ़कर तकलीफ नहीं देते और (चाहे कुछ हो मगर) जब बात कहो तो इन्साफ़ से अगरचे वह (जिसके तुम ख़िलाफ न हो) तुम्हारा अज़ीज़ ही (क्यों न) हो और ख़ुदा के एहद व पैग़ाम को पूरा करो यह वह बातें हैं जिनका ख़ुदा ने तुम्हे हुक्म दिया है कि तुम इबरत हासिल करो और ये भी (समझ लो) कि यही मेरा सीधा रास्ता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,153,'Al-An''aam','وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمࣰ ا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ','اور یہ کہ میرا سیدھا رستہ یہی ہے تو تم اسی پر چلنا اور اور رستوں پر نہ چلنا کہ (ان پر چل کر) خدا کے رستے سے الگ ہو جاؤ گے ان باتوں کا خدا تمہیں حکم دیتا ہے تاکہ تم پرہیزگار بنو','Indeed, that is My Path—perfectly straight. So follow it and do not follow other ways, for they will lead you away from His Way. This is what He has commanded you, so perhaps you will be conscious ˹of Allah˺.”','तो उसी पर चले जाओ और दूसरे रास्ते पर न चलो कि वह तुमको ख़ुदा के रास्ते से (भटकाकर) तितिर बितिर कर देगें यह वह बातें हैं जिनका ख़ुदा ने तुमको हक्म दिया है ताकि तुम परहेज़गार बनो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,154,'Al-An''aam','ثُمَّ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ تَمَامًا عَلَى ٱلَّذِيٓ أَحۡسَنَ وَتَفۡصِيلࣰ ا لِّكُلِّ شَيۡءࣲ وَهُدࣰ ى وَرَحۡمَةࣰ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمۡ يُؤۡمِنُونَ','(ہاں) پھر (سن لو کہ) ہم نے موسیؑ کو کتاب عنایت کی تھی تاکہ ان لوگوں پر جو نیکوکار ہیں نعمت پوری کر دیں اور (اس میں) ہر چیز کا بیان (ہے) اور ہدایت (ہے) اور رحمت ہے تاکہ (ان کی امت کے) لوگ اپنے پروردگار کے رُوبرو حاضر ہونے کا یقین کریں','Additionally, We gave Moses the Scripture, completing the favour upon those who do good, detailing everything, and as a guide and a mercy, so perhaps they would be certain of the meeting with their Lord','फिर हमनें जो नेक़ी करें उस पर अपनी नेअमत पूरी करने के वास्ते मूसा को क़िताब (तौरौत) अता फरमाई और उसमें हर चीज़ की तफ़सील (बयान कर दी ) थी और (लोगों के लिए अज़सरतापा(सर से पैर तक)) हिदायत व रहमत है ताकि वह लोग अपनें परवरदिगार के सामने हाज़िर होने का यक़ीन करें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,155,'Al-An''aam','وَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكࣱ فَٱتَّبِعُوهُ وَٱتَّقُواْ لَعَلَّكُمۡ تُرۡحَمُونَ','اور (اے کفر کرنے والوں) یہ کتاب بھی ہمیں نے اتاری ہے برکت والی تو اس کی پیروی کرو اور (خدا سے) ڈرو تاکہ تم پر مہربانی کی جائے','This is a blessed Book We have revealed. So follow it and be mindful ˹of Allah˺, so you may be shown mercy','और ये किताब (क़ुरान) जिसको हमने (अब नाज़िल किया है क्या है-बरक़त वाली किताब) है तो तुम लोग उसी की पैरवी करो (और ख़ुदा से) डरते रहो ताकि तुम पर रहम किया जाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,156,'Al-An''aam','أَن تَقُولُوٓاْ إِنَّمَآ أُنزِلَ ٱلۡكِتَٰبُ عَلَىٰ طَآئِفَتَيۡنِ مِن قَبۡلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمۡ لَغَٰفِلِينَ','(اور اس لیے اتاری ہے) کہ (تم یوں نہ) کہو کہ ہم سے پہلے دو ہی گروہوں پر کتابیں اتری تھیں اور ہم ان کے پڑھنے سے (معذور اور) بےخبر تھے','You ˹pagans˺ can no longer say, “Scriptures were only revealed to two groups before us and we were unaware of their teachings.”','(और ऐ मुशरेकीन ये किताब हमने इसलिए नाज़िल की कि तुम कहीं) यह कह बैठो कि हमसे पहले किताब ख़ुदा तो बस सिर्फ दो ही गिरोहों (यहूद व नसारा) पर नाज़िल हुई थी अगरचे हम तो उनके पढ़ने (पढ़ाने) से बेखबर थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,157,'Al-An''aam','أَوۡ تَقُولُواْ لَوۡ أَنَّآ أُنزِلَ عَلَيۡنَا ٱلۡكِتَٰبُ لَكُنَّآ أَهۡدَىٰ مِنۡهُمۡۚ فَقَدۡ جَآءَكُم بَيِّنَةࣱ مِّن رَّبِّكُمۡ وَهُدࣰ ى وَرَحۡمَةࣱۚ فَمَنۡ أَظۡلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنۡهَاۗ سَنَجۡزِي ٱلَّذِينَ يَصۡدِفُونَ عَنۡ ءَايَٰتِنَا سُوٓءَ ٱلۡعَذَابِ بِمَا كَانُواْ يَصۡدِفُونَ','یا (یہ نہ) کہو کہ اگر ہم پر بھی کتاب نازل ہوتی تو ہم ان لوگوں کی نسبت کہیں سیدھے رستے پر ہوتے سو تمہارے پاس تمہارے پروردگار کی طرف سے دلیل اور ہدایت اور رحمت آ گئی ہے تو اس سے بڑھ کر ظالم کون ہوگا جو خدا کی آیتوں کی تکذیب کرے اور ان سے (لوگوں کو) پھیرے جو لوگ ہماری آیتوں سے پھیرتے ہیں اس پھیرنے کے سبب ہم ان کو برے عذاب کی سزا دیں گے','Nor can you say, “If only the Scriptures had been revealed to us, we would have been better guided than they.” Now there has come to you from your Lord a clear proof—a guide and mercy. Who then does more wrong than those who deny Allah’s revelations and turn away from them? We will reward those who turn away from Our revelations with a dreadful punishment for turning away','या ये कहने लगो कि अगर हम पर किताबे (ख़ुदा नाज़िल होती तो हम उन लोगों से कहीं बढ़कर राहे रास्त पर होते तो (देखो) अब तो यक़ीनन तुम्हारे परवरदिगार की तरफ से तुम्हारे पास एक रौशन दलील है (किताबे ख़ुदा) और हिदायत और रहमत आ चुकी तो जो शख्स ख़ुदा के आयात को झुठलाए और उससे मुँह फेरे उनसे बढ़ कर ज़ालिम कौन है जो लोग हमारी आयतों से मुँह फेरते हैं हम उनके मुँह फेरने के बदले में अनक़रीब ही बुरे अज़ाब की सज़ा देगें (ऐ रसूल) क्या ये लोग सिर्फ उसके मुन्तिज़र है कि उनके पास फरिश्ते आएं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,158,'Al-An''aam','هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَٰٓئِكَةُ أَوۡ يَأۡتِيَ رَبُّكَ أَوۡ يَأۡتِيَ بَعۡضُ ءَايَٰتِ رَبِّكَۗ يَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرࣰ اۗ قُلِ ٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ','یہ اس کے سوا اور کس بات کے منتظر ہیں کہ ان کے پاس فرشتے آئیں یا خود تمہارا پروردگار آئے یا تمہارے پروردگار کی کچھ نشانیاں آئیں (مگر) جس روز تمہارے پروردگار کی کچھ نشانیاں آ جائیں گی تو جو شخص پہلے ایمان نہیں لایا ہوگا اس وقت اسے ایمان لانا کچھ فائدہ نہیں دے گا یا اپنے ایمان (کی حالت) میں نیک عمل نہیں کئے ہوں گے (تو گناہوں سے توبہ کرنا مفید نہ ہوگا اے پیغمبر ان سے) کہہ دو کہ تم بھی انتظار کرو ہم بھی انتظار کرتے ہیں','Are they awaiting the coming of the angels, or your Lord ˹Himself˺, or some of your Lord’s ˹major˺ signs? On the Day your Lord’s signs arrive, belief will not benefit those who did not believe earlier or those who did no good through their faith. Say, “Keep waiting! We too are waiting.”','या तुम्हारा परवरदिगार खुद (तुम्हारे पास) आये या तुम्हारे परवरदिगार की कुछ निशानियाँ आ जाएं (आख़िरकार क्योकर समझाया जाए) हालांकि जिस दिन तुम्हारे परवरदिगार की बाज़ निशानियाँ आ जाएंगी तो जो शख्स पहले से ईमान नहीं लाया होगा या अपने मोमिन होने की हालत में कोई नेक काम नहीं किया होगा तो अब उसका ईमान लाना उसको कुछ भी मुफ़ीद न होगा - (ऐ रसूल) तुम (उनसे) कह दो कि (अच्छा यही सही) तुम (भी) इन्तिज़ार करो हम भी इन्तिज़ार करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,159,'Al-An''aam','إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعࣰ ا لَّسۡتَ مِنۡهُمۡ فِي شَيۡءٍۚ إِنَّمَآ أَمۡرُهُمۡ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُواْ يَفۡعَلُونَ','جن لوگوں نے اپنے دین میں (بہت سے) رستے نکالے اور کئی کئی فرقے ہو گئے ان سے تم کو کچھ کام نہیں ان کا کام خدا کے حوالے پھر جو کچھ وہ کرتے رہے ہیں وہ ان کو (سب) بتائے گا','Indeed, you ˹O Prophet˺ are not responsible whatsoever for those who have divided their faith and split into sects. Their judgment rests only with Allah. And He will inform them of what they used to do','बेशक जिन लोगों ने आपने दीन में तफरक़ा डाला और कई फरीक़ बन गए थे उनसे कुछ सरोकार नहीं उनका मामला तो सिर्फ ख़ुदा के हवाले है फिर जो कुछ वह दुनिया में नेक या बद किया करते थे वह उन्हें बता देगा (उसकी रहमत तो देखो)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,160,'Al-An''aam','مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَا وَهُمۡ لَا يُظۡلَمُونَ','اور جو کوئی (خدا کے حضور) نیکی لے کر آئے گا اس کو ویسی دس نیکیاں ملیں گی اور جو برائی لائے گا اسے سزا ویسے ہی ملے گی اور ان پر ظلم نہیں کیا جائے گا','Whoever comes with a good deed will be rewarded tenfold. But whoever comes with a bad deed will be punished for only one. None will be wronged','जो शख्स नेकी करेगा तो उसको दस गुना सवाब अता होगा और जो शख्स बदी करेगा तो उसकी सज़ा उसको बस उतनी ही दी जाएगी और वह लोग (किसी तरह) सताए न जाएगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,161,'Al-An''aam','قُلۡ إِنَّنِي هَدَىٰنِي رَبِّيٓ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ دِينࣰ ا قِيَمࣰ ا مِّلَّةَ إِبۡرَٰهِيمَ حَنِيفࣰ اۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ','کہہ دو کہ مجھے میرے پروردگار نے سیدھا رستہ دکھا دیا ہے (یعنی دین صحیح) مذہب ابراہیم کا جو ایک (خدا) ہی کی طرف کے تھے اور مشرکوں میں سے نہ تھے','Say, ˹O Prophet,˺ “Surely my Lord has guided me to the Straight Path, a perfect way, the faith of Abraham, the upright, who was not one of the polytheists.”','(ऐ रसूल) तुम उनसे कहो कि मुझे तो मेरे परवरदिगार ने सीधी राह यानि एक मज़बूत दीन इबराहीम के मज़हब की हिदायत फरमाई है बातिल से कतरा के चलते थे और मुशरेकीन से न थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,162,'Al-An''aam','قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ','(یہ بھی) کہہ دو کہ میری نماز اور میری عبادت اور میرا جینا اور میرا مرنا سب خدائے رب العالمین ہی کے لیے ہے','Say, “Surely my prayer, my worship, my life, and my death are all for Allah—Lord of all worlds','(ऐ रसूल) तुम उन लोगों से कह दो कि मेरी नमाज़ मेरी इबादत मेरा जीना मेरा मरना सब ख़ुदा ही के वास्ते है जो सारे जहाँ का परवरदिगार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,163,'Al-An''aam','لَا شَرِيكَ لَهُۥۖ وَبِذَٰلِكَ أُمِرۡتُ وَأَنَا۠ أَوَّلُ ٱلۡمُسۡلِمِينَ','جس کا کوئی شریک نہیں اور مجھ کو اسی بات کا حکم ملا ہے اور میں سب سے اول فرمانبردار ہوں','He has no partner. So I am commanded, and so I am the first to submit.”','और उसका कोई शरीक़ नहीं और मुझे इसी का हुक्म दिया गया है और मैं सबसे पहले इस्लाम लाने वाला हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,164,'Al-An''aam','قُلۡ أَغَيۡرَ ٱللَّهِ أَبۡغِي رَبࣰّ ا وَهُوَ رَبُّ كُلِّ شَيۡءࣲۚ وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ','کہو کیا میں خدا کے سوا اور پروردگار تلاش کروں اور وہی تو ہر چیز کا مالک ہے اور جو کوئی (برا) کام کرتا ہے تو اس کا ضرر اسی کو ہوتا ہے اور کوئی شخص کسی (کے گناہ) کا بوجھ نہیں اٹھائے گا پھر تم سب کو اپنے پروردگار کی طرف لوٹ کا جانا ہے تو جن جن باتوں میں تم اختلاف کیا کرتے تھے وہ تم کو بتائے گا','Say, ˹O Prophet,˺ “Should I seek a lord other than Allah while He is the Lord of everything?” No one will reap except what they sow. No soul burdened with sin will bear the burden of another. Then to your Lord is your return, and He will inform you of your differences','(ऐ रसूल) तुम पूछो तो कि क्या मैं ख़ुदा के सिवा किसी और को परवरदिगार तलाश करुँ हालॉकि वह तमाम चीज़ो का मालिक है और जो शख्स कोई बुरा काम करता है उसका (वबाल) उसी पर है और कोई शख्स किसी दूसरे के गुनाह का बोझ नहीं उठाने का फिर तुम सबको अपने परवरदिगार के हुज़ूर में लौट कर जाना है तब तुम लोग जिन बातों में बाहम झगड़ते थे वह सब तुम्हें बता देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (6,165,'Al-An''aam','وَهُوَ ٱلَّذِي جَعَلَكُمۡ خَلَٰٓئِفَ ٱلۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضࣲ دَرَجَٰتࣲ لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۗ إِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورࣱ رَّحِيمُۢ','اور وہی تو ہے جس نے زمین میں تم کو اپنا نائب بنایا اور ایک کے دوسرے پر درجے بلند کئے تاکہ جو کچھ اس نے تمہیں بخشا ہے اس میں تمہاری آزمائش ہے بےشک تمہارا پروردگار جلد عذاب دینے والا ہے اور بےشک وہ بخشنے والا مہربان بھی ہے','He is the One Who has placed you as successors on earth and elevated some of you in rank over others, so He may test you with what He has given you. Surely your Lord is swift in punishment, but He is certainly All-Forgiving, Most Merciful','और वही तो वह (ख़ुदा) है जिसने तुम्हें ज़मीन में (अपना) नायब बनाया और तुममें से बाज़ के बाज़ पर दर्जे बुलन्द किये ताकि वो (नेअमत) तुम्हें दी है उसी पर तुम्हारा इमतेहान करे उसमें तो शक ही नहीं कि तुम्हारा परवरदिगार बहुत जल्द अज़ाब करने वाला है और इसमें भी शक नहीं कि वह बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,1,'Al-A''raaf','الٓمٓصٓ','المص','Alif-Lãm-Mĩm-Ṣãd','अलिफ़ लाम मीम स्वाद');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,2,'Al-A''raaf','كِتَٰبٌ أُنزِلَ إِلَيۡكَ فَلَا يَكُن فِي صَدۡرِكَ حَرَجࣱ مِّنۡهُ لِتُنذِرَ بِهِۦ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ','(اے محمدﷺ) یہ کتاب (جو) تم پر نازل ہوئی ہے۔ اس سے تمہیں تنگ دل نہیں ہونا چاہیئے، (یہ نازل) اس لیے (ہوئی ہے) کہ تم اس کے ذریعے سے (لوگوں) کو ڈر سناؤ اور (یہ) ایمان والوں کے لیے نصیحت ہے','˹This is˺ a Book sent down to you ˹O Prophet˺—do not let anxiety into your heart regarding it—so with it you may warn ˹the disbelievers˺, and as a reminder to the believers','(ऐ रसूल) ये किताब ख़ुदा (क़ुरान) तुम पर इस ग़रज़ से नाज़िल की गई है ताकि तुम उसके ज़रिये से लोगों को अज़ाबे ख़ुदा से डराओ और ईमानदारों के लिए नसीहत का बायस हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,3,'Al-A''raaf','ٱتَّبِعُواْ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡ وَلَا تَتَّبِعُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۗ قَلِيلࣰ ا مَّا تَذَكَّرُونَ','(لوگو) جو (کتاب) تم پر تمہارے پروردگار کے ہاں نازل ہوئی ہے اس کی پیروی کرو اور اس کے سوا اور رفیقوں کی پیروی نہ کرو (اور) تم کم ہی نصیحت قبول کرتے ہو','Follow what has been sent down to you from your Lord, and do not take others as guardians besides Him. How seldom are you mindful','तुम्हारे दिल में उसकी वजह से कोई न तंगी पैदा हो (लोगों) जो तुम्हारे परवरदिगार की तरफ से तुम पर नाज़िल किया गया है उसकी पैरवी करो और उसके सिवा दूसरे (फर्ज़ी) बुतों (माबुदों) की पैरवी न करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,4,'Al-A''raaf','وَكَم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا فَجَآءَهَا بَأۡسُنَا بَيَٰتًا أَوۡ هُمۡ قَآئِلُونَ','اور کتنی ہی بستیاں ہیں کہ ہم نے تباہ کر ڈالیں جن پر ہمارا عذاب (یا تو رات کو) آتا تھا جبکہ وہ سوتے تھے یا (دن کو) جب وہ قیلولہ (یعنی دوپہر کو آرام) کرتے تھے','˹Imagine˺ how many societies We have destroyed! Our torment took them by surprise ˹while sleeping˺ at night or midday','तुम लोग बहुत ही कम नसीहत क़ुबूल करते हो और क्या (तुम्हें) ख़बर नहीं कि ऐसी बहुत सी बस्तियाँ हैं जिन्हें हमने हलाक कर डाला तो हमारा अज़ाब (ऐसे वक्त) आ पहुचा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,5,'Al-A''raaf','فَمَا كَانَ دَعۡوَىٰهُمۡ إِذۡ جَآءَهُم بَأۡسُنَآ إِلَّآ أَن قَالُوٓاْ إِنَّا كُنَّا ظَٰلِمِينَ','تو جس وقت ان پر عذاب آتا تھا ان کے منہ سے یہی نکلتا تھا کہ (ہائے) ہم (ہائے) ہم (اپنے اوپر) ظلم کرتے رہے','Their only cry—when overwhelmed by Our torment—was, “We have indeed been wrongdoers.”','कि वह लोग या तो रात की नींद सो रहे थे या दिन को क़लीला (खाने के बाद का लेटना) कर रहे थे तब हमारा अज़ाब उन पर आ पड़ा तो उनसे सिवाए इसके और कुछ न कहते बन पड़ा कि हम बेशक ज़ालिम थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,6,'Al-A''raaf','فَلَنَسۡـَٔلَنَّ ٱلَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ وَلَنَسۡـَٔلَنَّ ٱلۡمُرۡسَلِينَ','تو جن لوگوں کی طرف پیغمبر بھیجے گئے ہم ان سے بھی پرسش کریں گے اور پیغمبروں سے بھی پوچھیں گے','We will surely question those who received messengers and We will question the messengers ˹themselves˺','फिर हमने तो ज़रूर उन लोगों से जिनकी तरफ पैग़म्बर भेजे गये थे (हर चीज़ का) सवाल करेगें और ख़ुद पैग़म्बरों से भी ज़रूर पूछेगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,7,'Al-A''raaf','فَلَنَقُصَّنَّ عَلَيۡهِم بِعِلۡمࣲۖ وَمَا كُنَّا غَآئِبِينَ','پھر اپنے علم سے ان کے حالات بیان کریں گے اور ہم کہیں غائب تو نہیں تھے','Then We will give them a full account with sure knowledge—for We were never absent','फिर हम उनसे हक़ीक़त हाल ख़ूब समझ बूझ के (ज़रा ज़रा) दोहराएगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,8,'Al-A''raaf','وَٱلۡوَزۡنُ يَوۡمَئِذٍ ٱلۡحَقُّۚ فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','اور اس روز (اعمال کا) تلنا برحق ہے تو جن لوگوں کے (عملوں کے) وزن بھاری ہوں گے وہ تو نجات پانے والے ہیں','The weighing on that Day will be just. As for those whose scale will be heavy ˹with good deeds˺, ˹only˺ they will be successful','और हम कुछ ग़ायब तो थे नहीं और उस दिन (आमाल का) तौला जाना बिल्कुल ठीक है फिर तो जिनके (नेक अमाल के) पल्ले भारी होगें तो वही लोग फायज़ुलहराम (नजात पाये हुए) होगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,9,'Al-A''raaf','وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُم بِمَا كَانُواْ بِـَٔايَٰتِنَا يَظۡلِمُونَ','اور جن کے وزن ہلکے ہوں گے تو یہی لوگ ہیں جنہوں نے اپنے تئیں خسارے میں ڈالا اس لیے کہ ہماری آیتوں کے بارے میں بےانصافی کرتے تھے','But those whose scale is light, they have doomed themselves for wrongfully denying Our signs','(और जिनके नेक अमाल के) पल्ले हलके होगें तो उन्हीं लोगों ने हमारी आयत से नाफरमानी करने की वजह से यक़ीनन अपना आप नुक़सान किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,10,'Al-A''raaf','وَلَقَدۡ مَكَّنَّٰكُمۡ فِي ٱلۡأَرۡضِ وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَۗ قَلِيلࣰ ا مَّا تَشۡكُرُونَ','اور ہم ہی نے زمین میں تمہارا ٹھکانہ بنایا اور اس میں تمہارے لیے سامان معشیت پیدا کئے۔ (مگر) تم کم ہی شکر کرتے ہو','We have indeed established you on earth and provided you with a means of livelihood. ˹Yet˺ you seldom give any thanks','और (ऐ बनीआदम) हमने तो यक़ीनन तुमको ज़मीन में क़ुदरत व इख़तेदार दिया और उसमें तुम्हारे लिए असबाब ज़िन्दगी मुहय्या किए (मगर) तुम बहुत ही कम शुक्र करते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,11,'Al-A''raaf','وَلَقَدۡ خَلَقۡنَٰكُمۡ ثُمَّ صَوَّرۡنَٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ لَمۡ يَكُن مِّنَ ٱلسَّٰجِدِينَ','اور ہم ہی نے تم کو (ابتدا میں مٹی سے) پیدا کیا پھر تمہاری صورت شکل بنائی پھر فرشتوں کو حکم دیا آدم کے آگے سجدہ کرو تو (سب نے) سجدہ کیا لیکن ابلیس کہ وہ سجدہ کرنے والوں میں (شامل) نہ ہوا','Surely We created you, then shaped you, then said to the angels, “Prostrate before Adam,” so they all did—but not Iblîs, who refused to prostrate with the others','हालाकि इसमें तो शक ही नहीं कि हमने तुम्हारे बाप आदम को पैदा किया फिर तुम्हारी सूरते बनायीं फिर हमनें फ़रिश्तों से कहा कि तुम सब के सब आदम को सजदा करो तो सब के सब झुक पड़े मगर शैतान कि वह सजदा करने वालों में शामिल न हुआ।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,12,'Al-A''raaf','قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرࣱ مِّنۡهُ خَلَقۡتَنِي مِن نَّارࣲ وَخَلَقۡتَهُۥ مِن طِينࣲ‏','(خدا نے) فرمایا جب میں نے تجھ کو حکم دیا تو کس چیز نے تجھے سجدہ کرنے سے باز رکھا۔ اس نے کہا کہ میں اس سے افضل ہوں۔ مجھے تو نے آگ سے پیدا کیا ہے اور اسے مٹی سے بنایا ہے','Allah asked, “What prevented you from prostrating when I commanded you?” He replied, “I am better than he is: You created me from fire and him from clay.”','ख़ुदा ने (शैतान से) फरमाया जब मैनें तुझे हुक्म दिया कि तू फिर तुझे सजदा करने से किसी ने रोका कहने लगा मैं उससे अफ़ज़ल हूँ (क्योंकि) तूने मुझे आग (ऐसे लतीफ अनसर) से पैदा किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,13,'Al-A''raaf','قَالَ فَٱهۡبِطۡ مِنۡهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ','فرمایا تو (بہشت سے) اتر جا تجھے شایاں نہیں کہ یہاں غرور کرے پس نکل جا۔ تو ذلیل ہے','Allah said, “Then get down from Paradise! It is not for you to be arrogant here. So get out! You are truly one of the disgraced.”','और उसको मिट्टी (ऐसी कशीफ़ अनसर) से पैदा किया ख़ुदा ने फरमाया (तुझको ये ग़ुरूर है) तो बेहश्त से नीचे उतर जाओ क्योंकि तेरी ये मजाल नहीं कि तू यहाँ रहकर ग़ुरूर करे तो यहाँ से (बाहर) निकल बेशक तू ज़लील लोगों से है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,14,'Al-A''raaf','قَالَ أَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ','اس نے کہا کہ مجھے اس دن تک مہلت عطا فرما جس دن لوگ (قبروں سے) اٹھائے جائیں گے','He appealed, “Then delay my end until the Day of their resurrection.”','कहने लगा तो (ख़ैर) हमें उस दिन तक की (मौत से) मोहलत दे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,15,'Al-A''raaf','قَالَ إِنَّكَ مِنَ ٱلۡمُنظَرِينَ','فرمایا (اچھا) تجھ کو مہلت دی جاتی ہے','Allah said, “You are delayed ˹until the appointed Day˺.”','जिस दिन सारी ख़ुदाई के लोग दुबारा जिलाकर उठा खड़े किये जाएगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,16,'Al-A''raaf','قَالَ فَبِمَآ أَغۡوَيۡتَنِي لَأَقۡعُدَنَّ لَهُمۡ صِرَٰطَكَ ٱلۡمُسۡتَقِيمَ','(پھر) شیطان نے کہا مجھے تو تُو نے ملعون کیا ہی ہے میں بھی تیرے سیدھے رستے پر ان (کو گمراہ کرنے) کے لیے بیٹھوں گا','He said, “For leaving me to stray I will lie in ambush for them on Your Straight Path','फ़रमाया (अच्छा मंजूर) तुझे ज़रूर मोहलत दी गयी कहने लगा चूँकि तूने मेरी राह मारी तो मैं भी तेरी सीधी राह पर बनी आदम को (गुमराह करने के लिए) ताक में बैठूं तो सही');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,17,'Al-A''raaf','ثُمَّ لَأٓتِيَنَّهُم مِّنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَيۡمَٰنِهِمۡ وَعَن شَمَآئِلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَٰكِرِينَ','پھر ان کے آگے سے اور پیچھے سے دائیں سے اور بائیں سے (غرض ہر طرف سے) آؤں گا (اور ان کی راہ ماروں گا) اور تو ان میں اکثر کو شکر گزار نہیں پائے گا','I will approach them from their front, their back, their right, their left, and then You will find most of them ungrateful.”','फिर उन लोगों से और उनके पीछे से और उनके दाहिने से और उनके बाएं से (गरज़ हर तरफ से) उन पर आ पडूंगा और (उनको बहकाउंगा) और तू उन में से बहुतरों की शुक्रग़ुज़ार नहीं पायेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,18,'Al-A''raaf','قَالَ ٱخۡرُجۡ مِنۡهَا مَذۡءُومࣰ ا مَّدۡحُورࣰ اۖ لَّمَن تَبِعَكَ مِنۡهُمۡ لَأَمۡلَأَنَّ جَهَنَّمَ مِنكُمۡ أَجۡمَعِينَ','(خدا نے) فرمایا، نکل جا۔ یہاں سے پاجی۔ مردود جو لوگ ان میں سے تیری پیروی کریں گے میں (ان کو اور تجھ کو جہنم میں ڈال کر) تم سب سے جہنم کو بھر دوں گا','Allah said, “Get out of Paradise! You are disgraced and rejected! I will certainly fill up Hell with you and your followers all together.”','ख़ुदा ने फरमाया यहाँ से बुरे हाल में (राइन्दा होकर निकल) (दूर) जा उन लोगों से जो तेरा कहा मानेगा तो मैं यक़ीनन तुम (और उन) सबको जहन्नुम में भर दूंगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,19,'Al-A''raaf','وَيَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ فَكُلَا مِنۡ حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ','اور ہم نے آدم (سے کہا کہ) تم اور تمہاری بیوی بہشت میں رہو سہو اور جہاں سے چاہو (اور جو چاہو) نوش جان کرو مگر اس درخت کے پاس نہ جاؤ ورنہ گنہگار ہو جاؤ گے','˹Allah said,˺ “O Adam! Live with your wife in Paradise and eat from wherever you please, but do not approach this tree, or else you will be wrongdoers.”','और (आदम से कहा) ऐ आदम तुम और तुम्हारी बीबी (दोनों) बेहश्त में रहा सहा करो और जहाँ से चाहो खाओ (पियो) मगर (ख़बरदार) उस दरख्त के करीब न जाना वरना तुम अपना आप नुक़सान करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,20,'Al-A''raaf','فَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَٰلِدِينَ','تو شیطان دونوں کو بہکانے لگا تاکہ ان کی ستر کی چیزیں جو ان سے پوشیدہ تھیں کھول دے اور کہنے لگا کہ تم کو تمہارے پروردگار نے اس درخت سے صرف اس لیے منع کیا ہے کہ کہ تم فرشتے نہ بن جاؤ یا ہمیشہ جیتے نہ رہو','Then Satan tempted them in order to expose what was hidden of their nakedness. He said, “Your Lord has forbidden this tree to you only to prevent you from becoming angels or immortals.”','फिर शैतान ने उन दोनों को वसवसा (शक) दिलाया ताकि (नाफरमानी की वजह से) उनके अस्तर की चीज़े जो उनकी नज़र से बेहश्ती लिबास की वजह से पोशीदा थी खोल डाले कहने लगा कि तुम्हारे परवरदिगार ने दोनों को दरख्त (के फल खाने) से सिर्फ इसलिए मना किया है (कि मुबादा) तुम दोनों फरिश्ते बन जाओ या हमेशा (ज़िन्दा) रह जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,21,'Al-A''raaf','وَقَاسَمَهُمَآ إِنِّي لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ','اور ان سے قسم کھا کر کہا میں تو تمہارا خیر خواہ ہوں','And he swore to them, “I am truly your sincere advisor.”','और उन दोनों के सामने क़समें खायीं कि मैं यक़ीनन तुम्हारा ख़ैर ख्वाह हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,22,'Al-A''raaf','فَدَلَّىٰهُمَا بِغُرُورࣲۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيۡطَٰنَ لَكُمَا عَدُوࣱّ مُّبِينࣱ‏','غرض (مردود نے) دھوکہ دے کر ان کو (معصیت کی طرف) کھینچ ہی لیا جب انہوں نے اس درخت (کے پھل) کو کھا لیا تو ان کی ستر کی چیزیں کھل گئیں اور وہ بہشت کے (درختوں کے) پتے توڑ توڑ کر اپنے اوپر چپکانے لگے اور (ستر چھپانے لگے) تب ان کے پروردگار نے ان کو پکارا کہ کیا میں نے تم کو اس درخت (کے پاس جانے) سے منع نہیں کیا تھا اور جتا نہیں دیا تھا کہ شیطان تمہارا کھلم کھلا دشمن ہے','So he brought about their fall through deception. And when they tasted of the tree, their nakedness was exposed to them, prompting them to cover themselves with leaves from Paradise. Then their Lord called out to them, “Did I not forbid you from that tree and ˹did I not˺ tell you that Satan is your sworn enemy?”','ग़रज़ धोखे से उन दोनों को उस (के खाने) की तरफ ले गया ग़रज़ जो ही उन दोनों ने इस दरख्त (के फल) को चखा कि (बेहश्ती लिबास गिर गया और समझ पैदा हुई) उन पर उनकी शर्मगाहें ज़ाहिर हो गयीं और बेहश्त के पत्ते (तोड़ जोड़ कर) अपने ऊपर ढापने लगे तब उनको परवरदिगार ने उनको आवाज़ दी कि क्यों मैंने तुम दोनों को इस दरख्त के पास (जाने) से मना नहीं किया था और (क्या) ये न जता दिया था कि शैतान तुम्हारा यक़ीनन खुला हुआ दुश्मन है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,23,'Al-A''raaf','قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ','دونوں عرض کرنے لگے کہ پروردگار ہم نے اپنی جانوں پر ظلم کیا اور اگر تو ہمیں نہیں بخشے گا اور ہم پر رحم نہیں کرے گا تو ہم تباہ ہو جائیں گے','They replied, “Our Lord! We have wronged ourselves. If You do not forgive us and have mercy on us, we will certainly be losers.”','ये दोनों अर्ज क़रने लगे ऐ हमारे पालने वाले हमने अपना आप नुकसान किया और अगर तू हमें माफ न फरमाएगा और हम पर रहम न करेगा तो हम बिल्कुल घाटे में ही रहेगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,24,'Al-A''raaf','قَالَ ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرࣱّ وَمَتَٰعٌ إِلَىٰ حِينࣲ‏','(خدا نے) فرمایا (تم سب بہشت سے) اتر جاؤ (اب سے) تم ایک دوسرے کے دشمن ہو اور تمہارے لیے ایک وقت (خاص) تک زمین پر ٹھکانہ اور (زندگی کا) سامان (کر دیا گیا) ہے','Allah said, “Descend as enemies to each other. You will find in the earth a residence and provision for your appointed stay.”','हुक्म हुआ तुम (मियां बीबी शैतान) सब के सब बेहशत से नीचे उतरो तुममें से एक का एक दुश्मन है और (एक ख़ास) वक्त तक तुम्हारा ज़मीन में ठहराव (ठिकाना) और ज़िन्दगी का सामना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,25,'Al-A''raaf','قَالَ فِيهَا تَحۡيَوۡنَ وَفِيهَا تَمُوتُونَ وَمِنۡهَا تُخۡرَجُونَ','(یعنی) فرمایا کہ اسی میں تمہارا جینا ہوگا اور اسی میں مرنا اور اسی میں سے (قیامت کو زندہ کر کے) نکالے جاؤ گے','He added, “There you will live, there you will die, and from there you will be resurrected.”','ख़ुदा ने (ये भी) फरमाया कि तुम ज़मीन ही में जिन्दगी बसर करोगे और इसी में मरोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,26,'Al-A''raaf','يَٰبَنِيٓ ءَادَمَ قَدۡ أَنزَلۡنَا عَلَيۡكُمۡ لِبَاسࣰ ا يُوَٰرِي سَوۡءَٰتِكُمۡ وَرِيشࣰ اۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرࣱۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمۡ يَذَّكَّرُونَ','اے نبی آدم ہم نے تم پر پوشاک اتاری کہ تمہارا ستر ڈھانکے اور (تمہارے بدن کو) زینت (دے) اور (جو) پرہیزگاری کا لباس (ہے) وہ سب سے اچھا ہے۔ یہ خدا کی نشانیاں ہیں تاکہ لوگ نصحیت پکڑ یں','O children of Adam! We have provided for you clothing to cover your nakedness and as an adornment. However, the best clothing is righteousness. This is one of Allah’s bounties, so perhaps you will be mindful','और उसी में से (और) उसी में से फिर दोबारा तुम ज़िन्दा करके निकाले जाओगे ऐ आदम की औलाद हमने तुम्हारे लिए पोशाक नाज़िल की जो तुम्हारे शर्मगाहों को छिपाती है और ज़ीनत के लिए कपड़े और इसके अलावा परहेज़गारी का लिबास है और ये सब (लिबासों) से बेहतर है ये (लिबास) भी ख़ुदा (की कुदरत) की निशानियों से है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,27,'Al-A''raaf','يَٰبَنِيٓ ءَادَمَ لَا يَفۡتِنَنَّكُمُ ٱلشَّيۡطَٰنُ كَمَآ أَخۡرَجَ أَبَوَيۡكُم مِّنَ ٱلۡجَنَّةِ يَنزِعُ عَنۡهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوۡءَٰتِهِمَآۚ إِنَّهُۥ يَرَىٰكُمۡ هُوَ وَقَبِيلُهُۥ مِنۡ حَيۡثُ لَا تَرَوۡنَهُمۡۗ إِنَّا جَعَلۡنَا ٱلشَّيَٰطِينَ أَوۡلِيَآءَ لِلَّذِينَ لَا يُؤۡمِنُونَ','اے نبی آدم (دیکھنا کہیں) شیطان تمہیں بہکا نہ دے جس طرح تمہارے ماں باپ کو (بہکا کر) بہشت سے نکلوا دیا اور ان سے ان کے کپڑے اتروا دیئے تاکہ ان کے ستر ان کو کھول کر دکھا دے۔ وہ اور اس کے بھائی تم کو ایسی جگہ سے دیکھتے رہے ہیں جہاں سے تم ان کو نہیں دیکھ سکتے ہم نے شیطانوں کو انہیں لوگوں کا رفیق کار بنایا ہے جو ایمان نہیں رکھتے','O children of Adam! Do not let Satan deceive you as he tempted your parents out of Paradise and caused their cover to be removed in order to expose their nakedness. Surely he and his soldiers watch you from where you cannot see them. We have made the devils allies of those who disbelieve','ताकि लोग नसीहत व इबरत हासिल करें ऐ औलादे आदम (होशियार रहो) कहीं तुम्हें शैतान बहका न दे जिस तरह उसने तुम्हारे बाप माँ आदम व हव्वा को बेहश्त से निकलवा छोड़ा उसी ने उन दोनों से (बेहश्ती) पोशाक उतरवाई ताकि उन दोनों को उनकी शर्मगाहें दिखा दे वह और उसका क़ुनबा ज़रूर तुम्हें इस तरह देखता रहता है कि तुम उन्हे नहीं देखने पाते हमने शैतानों को उन्हीं लोगों का रफीक़ क़रार दिया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,28,'Al-A''raaf','وَإِذَا فَعَلُواْ فَٰحِشَةࣰ قَالُواْ وَجَدۡنَا عَلَيۡهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَاۗ قُلۡ إِنَّ ٱللَّهَ لَا يَأۡمُرُ بِٱلۡفَحۡشَآءِۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ','اور جب کوئی بے حیائی کا کام کرتے ہیں تو کہتے ہیں کہ ہم نے اپنے بزرگوں کو اسی طرح کرتے دیکھا ہے اور خدا نے بھی ہم کو یہی حکم دیا ہے۔ کہہ دو خدا بےحیائی کے کام کرنے کا ہرگز حکم نہیں دیتا۔ بھلا تم خدا کی نسبت ایسی بات کیوں کہتے ہو جس کا تمہیں علم نہیں','Whenever they commit a shameful deed, they say, “We found our forefathers doing it and Allah has commanded us to do it.” Say, “No! Allah never commands what is shameful. How can you attribute to Allah what you do not know?”','जो ईमान नही रखते और वह लोग जब कोई बुरा काम करते हैं कि हमने उस तरीके पर अपने बाप दादाओं को पाया और ख़ुदा ने (भी) यही हुक्म दिया है (ऐ रसूल) तुम साफ कह दो कि ख़ुदा ने (भी) यही हुक्म दिया है (ऐ रसूल) तुम (साफ) कह दो कि ख़ुदा हरगिज़ बुरे काम का हुक्म नहीं देता क्या तुम लोग ख़ुदा पर (इफ्तिरा करके) वह बातें कहते हो जो तुम नहीं जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,29,'Al-A''raaf','قُلۡ أَمَرَ رَبِّي بِٱلۡقِسۡطِۖ وَأَقِيمُواْ وُجُوهَكُمۡ عِندَ كُلِّ مَسۡجِدࣲ وَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۚ كَمَا بَدَأَكُمۡ تَعُودُونَ','کہہ دو کہ میرے پروردگار نے تو انصاف کرنے کا حکم دیا ہے۔ اور یہ کہ ہر نماز کے وقت سیدھا (قبلے کی طرف) رخ کیا کرو اور خاص اسی کی عبادت کرو اور اسی کو پکارو۔ اس نے جس طرح تم کو ابتداء میں پیدا کیا تھا اسی طرح تم پھر پیدا ہوگے','Say, ˹O Prophet,˺ “My Lord has commanded uprightness and dedication ˹to Him alone˺ in worship, calling upon Him with sincere devotion. Just as He first brought you into being, you will be brought to life again.”','(ऐ रसूल) तुम कह दो कि मेरे परवरदिगार ने तो इन्साफ का हुक्म दिया है और (ये भी क़रार दिया है कि) हर नमाज़ के वक्त अपने अपने मुँह (क़िबले की तरफ़) सीधे कर लिया करो और इसके लिए निरी खरी इबादत करके उससे दुआ मांगो जिस तरह उसने तुम्हें शुरू शुरू पैदा किया था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,30,'Al-A''raaf','فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيۡهِمُ ٱلضَّلَٰلَةُۚ إِنَّهُمُ ٱتَّخَذُواْ ٱلشَّيَٰطِينَ أَوۡلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ','ایک فریق کو تو اس نے ہدایت دی اور ایک فریق پر گمراہی ثابت ہوچکی۔ ان لوگوں نے خدا کو چھوڑ کر شیطانوں کو رفیق بنا لیا اور سمجھتے (یہ) ہیں کہ ہدایت یاب ہیں','He has guided some, while others are destined to stray. They have taken devils as their masters instead of Allah—thinking they are ˹rightly˺ guided','उसी तरह फिर (दोबारा) ज़िन्दा किये जाओगे उसी ने एक फरीक़ की हिदायत की और एक गिरोह (के सर) पर गुमराही सवार हो गई उन लोगों ने ख़ुदा को छोड़कर शैतानों को अपना सरपरस्त बना लिया और बावजूद उसके गुमराह करते हैं कि वह राह रास्ते पर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,31,'Al-A''raaf','۞يَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدࣲ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ','اے نبی آدم! ہر نماز کے وقت اپنے تئیں مزّین کیا کرو اور کھاؤ اور پیؤ اور بےجا نہ اڑاؤ کہ خدا بےجا اڑانے والوں کو دوست نہیں رکھتا','O Children of Adam! Dress properly whenever you are at worship. Eat and drink, but do not waste. Surely He does not like the wasteful','ऐ औलाद आदम हर नमाज़ के वक्त बन सवर के निखर जाया करो और खाओ और पियो और फिज़ूल ख़र्ची मत करो (क्योंकि) ख़ुदा फिज़ूल ख़र्च करने वालों को दोस्त नहीं रखता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,32,'Al-A''raaf','قُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةࣰ يَوۡمَ ٱلۡقِيَٰمَةِۗ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمࣲ يَعۡلَمُونَ','پوچھو تو کہ جو زینت (وآرائش) اور کھانے (پینے) کی پاکیزہ چیزیں خدا نے اپنے بندوں کے لیے پیدا کی ہیں ان کو حرام کس نے کیا ہے؟ کہہ دو کہ یہ چیزیں دنیا کی زندگی میں ایمان والوں کے لیے ہیں اور قیامت کے دن خاص ان ہی کا حصہ ہوں گی۔ اسی طرح خدا اپنی آیتیں سمجھنے والوں کے لیے کھول کھول کر بیان فرماتا ہے','Ask, ˹O Prophet,˺ “Who has forbidden the adornments and lawful provisions Allah has brought forth for His servants?” Say, “They are for the enjoyment of the believers in this worldly life, but they will be exclusively theirs on the Day of Judgment. This is how We make Our revelations clear for people of knowledge.”','(ऐ रसूल से) पूछो तो कि जो ज़ीनत (के साज़ों सामान) और खाने की साफ सुथरी चीज़ें ख़ुदा ने अपने बन्दो के वास्ते पैदा की हैं किसने हराम कर दी तुम ख़ुद कह दो कि सब पाक़ीज़ा चीज़े क़यामत के दिन उन लोगों के लिए ख़ास हैं जो दुनिया की (ज़रा सी) ज़िन्दगी में ईमान लाते थे हम यूँ अपनी आयतें समझदार लोगों के वास्ते तफसीलदार बयान करतें हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,33,'Al-A''raaf','قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡيَ بِغَيۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنࣰ ا وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ','کہہ دو کہ میرے پروردگار نے تو بےحیائی کی باتوں کو ظاہر ہوں یا پوشیدہ اور گناہ کو اور ناحق زیادتی کرنے کو حرام کیا ہے۔ اور اس کو بھی کہ تم کسی کو خدا کا شریک بناؤ جس کی اس نے کوئی سند نازل نہیں کی اور اس کو بھی کہ خدا کے بارے میں ایسی باتیں کہو جن کا تمہیں کچھ علم نہیں','Say, “My Lord has only forbidden open and secret indecencies, sinfulness, unjust aggression, associating ˹others˺ with Allah ˹in worship˺—a practice He has never authorized—and attributing to Allah what you do not know.”','(ऐ रसूल) तुम साफ कह दो कि हमारे परवरदिगार ने तो तमाम बदकारियों को ख्वाह (चाहे) ज़ाहिरी हो या बातिनी और गुनाह और नाहक़ ज्यादती करने को हराम किया है और इस बात को कि तुम किसी को ख़ुदा का शरीक बनाओ जिनकी उनसे कोई दलील न ही नाज़िल फरमाई और ये भी कि बे समझे बूझे ख़ुदा पर बोहतान बॉधों');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,34,'Al-A''raaf','وَلِكُلِّ أُمَّةٍ أَجَلࣱۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَأۡخِرُونَ سَاعَةࣰ وَلَا يَسۡتَقۡدِمُونَ','اور ہر ایک فرقے کے لیے (موت کا) ایک وقت مقرر ہے۔ جب وہ آ جاتا ہے تو نہ تو ایک گھڑی دیر کرسکتے ہیں نہ جلدی','For each community there is an appointed term. When their time arrives, they can neither delay it for a moment, nor could they advance it','और हर गिरोह (के न पैदा होने) का एक ख़ास वक्त है फिर जब उनका वक्त आ पहुंचता है तो न एक घड़ी पीछे रह सकते हैं और न आगे बढ़ सकते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,35,'Al-A''raaf','يَٰبَنِيٓ ءَادَمَ إِمَّا يَأۡتِيَنَّكُمۡ رُسُلࣱ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي فَمَنِ ٱتَّقَىٰ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ','اے نبی آدم! (ہم تم کو یہ نصیحت ہمیشہ کرتے رہے ہیں کہ) جب ہمارے پیغمبر تمہارے پاس آیا کریں اور ہماری آیتیں تم کو سنایا کریں (تو ان پر ایمان لایا کرو) کہ جو شخص (ان پر ایمان لا کر خدا سے) ڈرتا رہے گا اور اپنی حالت درست رکھے گا تو ایسے لوگوں کو نہ کچھ خوف ہوگا اور نہ وہ غمناک ہوں گے','O children of Adam! When messengers from among yourselves come to you reciting My revelations—whoever shuns evil and mends their ways, there will be no fear for them, nor will they grieve','ऐ औलादे आदम जब तुम में के (हमारे) पैग़म्बर तुम्हारे पास आए और तुमसे हमारे एहकाम बयान करे तो (उनकी इताअत करना क्योंकि जो शख्स परहेज़गारी और नेक काम करेगा तो ऐसे लोगों पर न तो (क़यामत में) कोई ख़ौफ़ होगा और न वह आर्ज़दा ख़ातिर (परेशान) होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,36,'Al-A''raaf','وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ','اور جنہوں نے ہماری آیتوں کو جھٹلایا اور ان سے سرتابی کی وہی دوزخی ہیں کہ ہمیشہ اس میں (جلتے) رہیں گے','But those who receive Our revelations with denial and arrogance will be the residents of the Fire. They will be there forever','और जिन लोगों ने हमारी आयतों को झुठलाया और उनसे सरताबी कर बैठे वह लोग जहन्नुमी हैं कि वह उसमें हमेशा रहेगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,37,'Al-A''raaf','فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ أُوْلَٰٓئِكَ يَنَالُهُمۡ نَصِيبُهُم مِّنَ ٱلۡكِتَٰبِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمۡ رُسُلُنَا يَتَوَفَّوۡنَهُمۡ قَالُوٓاْ أَيۡنَ مَا كُنتُمۡ تَدۡعُونَ مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ','تو اس سے زیادہ ظالم کون ہے جو خدا پر جھوٹ باندھے یا اس کی آیتوں کو جھٹلائے۔ ان کو ان کے نصیب کا لکھا ملتا ہی رہے گا یہاں تک کہ جب ان کے پاس ہمارے بھیجے ہوئے (فرشتے) جان نکالنے آئیں گے تو کہیں گے کہ جن کو تم خدا کے سوا پکارا کرتے تھے وہ (اب) کہاں ہیں؟ وہ کہیں گے (معلوم نہیں) کہ وہ ہم سے (کہاں) غائب ہوگئے اور اقرار کریں گے کہ بےشک وہ کافر تھے','Who does more wrong than those who fabricate lies against Allah or deny His revelations? They will receive what is destined for them, until Our messenger-angels arrive to take their souls, asking them, “Where are those ˹false gods˺ you used to invoke besides Allah?” They will cry, “They have failed us,” and they will confess against themselves that they were indeed disbelievers','तो जो शख्स ख़ुदा पर झूठ बोहतान बॉधे या उसकी आयतों को झुठलाए उससे बढ़कर ज़ालिम और कौन होगा फिर तो वह लोग हैं जिन्हें उनकी (तक़दीर) का लिखा हिस्सा (रिज़क) वग़ैरह मिलता रहेगा यहाँ तक कि जब हमारे भेजे हुए (फरिश्ते) उनके पास आकर उनकी रूह कब्ज़ करेगें तो (उनसे) पूछेगें कि जिन्हें तुम ख़ुदा को छोड़कर पुकारा करते थे अब वह (कहाँ हैं तो वह कुफ्फार) जवाब देगें कि वह सब तो हमें छोड़ कर चल चंपत हुए और अपने खिलाफ आप गवाही देगें कि वह बेशक काफ़िर थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,38,'Al-A''raaf','قَالَ ٱدۡخُلُواْ فِيٓ أُمَمࣲ قَدۡ خَلَتۡ مِن قَبۡلِكُم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِ فِي ٱلنَّارِۖ كُلَّمَا دَخَلَتۡ أُمَّةࣱ لَّعَنَتۡ أُخۡتَهَاۖ حَتَّىٰٓ إِذَا ٱدَّارَكُواْ فِيهَا جَمِيعࣰ ا قَالَتۡ أُخۡرَىٰهُمۡ لِأُولَىٰهُمۡ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمۡ عَذَابࣰ ا ضِعۡفࣰ ا مِّنَ ٱلنَّارِۖ قَالَ لِكُلࣲّ ضِعۡفࣱ وَلَٰكِن لَّا تَعۡلَمُونَ','تو خدا فرمائے گا کہ جنّوں اور انسانوں کی جو جماعتیں تم سے پہلے ہو گزری ہیں ان کے ساتھ تم بھی داخل جہنم ہو جاؤ۔ جب ایک جماعت (وہاں) جا داخل ہو گئی تو اپنی (مذہبی) بہن (یعنی اپنے جیسی دوسری جماعت) پر لعنت کرے گی۔ یہاں تک کہ جب سب اس میں داخل ہو جائیں گے تو پچھلی جماعت پہلی کی نسبت کہے گی کہ اے پروردگار! ان ہی لوگوں نے ہم کو گمراہ کیا تھا تو ان کو آتش جہنم کا دگنا عذاب دے۔ خدا فرمائے گا کہ (تم) سب کو دگنا (عذاب دیا جائے گا) مگر تم نہیں جانتے','Allah will say, “Enter the Fire along with the ˹evil˺ groups of jinn and humans that preceded you.” Whenever a group enters Hell, it will curse the preceding one until they are all gathered inside, the followers will say about their leaders, “Our Lord! They have misled us, so multiply their torment in the Fire.” He will answer, “It has already been multiplied for all, but you do not know.”','(तब ख़ुदा उनसे) फरमाएगा कि जो लोग जिन व इन्स के तुम से पहले बसे हैं उन्हीं में मिलजुल कर तुम भी जहन्नुम वासिल हो जाओ (और ) अहले जहन्नुम का ये हाल होगा कि जब उसमें एक गिरोह दाख़िल होगा तो अपने साथी दूसरे गिरोह पर लानत करेगा यहाँ तक कि जब सब के सब पहुंच जाएगें तो उनमें की पिछली जमात अपने से पहली जमाअत के वास्ते बदद्आ करेगी कि परवरदिगार उन्हीं लोगों ने हमें गुमराह किया था तो उन पर जहन्नुम का दोगुना अज़ाब फरमा (इस पर) ख़ुदा फरमाएगा कि हर एक के वास्ते दो गुना अज़ाब है लेकिन (तुम पर) तुफ़ है तुम जानते नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,39,'Al-A''raaf','وَقَالَتۡ أُولَىٰهُمۡ لِأُخۡرَىٰهُمۡ فَمَا كَانَ لَكُمۡ عَلَيۡنَا مِن فَضۡلࣲ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡسِبُونَ','اور پہلی جماعت پچھلی جماعت سے کہے گی کہ تم کو ہم پر کچھ بھی فضیلت نہ ہوئی تو جو (عمل) تم کیا کرتے تھے اس کے بدلے میں عذاب کے مزے چکھو','Then the leaders will say to their followers, “You were no better than us! So taste the torment for what you used to commit.”','और उनमें से पहली जमाअत पिछली जमाअत की तरफ मुख़ातिब होकर कहेगी कि अब तो तुमको हमपर कोई फज़ीलत न रही पस (हमारी तरह) तुम भी अपने करतूत की बदौलत अज़ाब (के मज़े) चखो बेशक जिन लोगों ने हमारे आयात को झुठलाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,40,'Al-A''raaf','إِنَّ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَٰبُ ٱلسَّمَآءِ وَلَا يَدۡخُلُونَ ٱلۡجَنَّةَ حَتَّىٰ يَلِجَ ٱلۡجَمَلُ فِي سَمِّ ٱلۡخِيَاطِۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُجۡرِمِينَ','جن لوگوں نے ہماری آیتوں کو جھٹلایا اور ان سے سرتابی کی۔ ان کے لیے نہ آسمان کے دروازے کھولے جائیں گے اور نہ وہ بہشت میں داخل ہوں گے۔ یہاں تک کہ اونٹ سوئی کے ناکے میں سے نہ نکل جائے اور گنہگاروں کو ہم ایسی ہی سزا دیا کرتے ہیں','Surely those who receive our revelations with denial and arrogance, the gates of heaven will not be opened for them, nor will they enter Paradise until a camel passes through the eye of a needle. This is how We reward the wicked','और उनसे सरताबी की न उनके लिए आसमान के दरवाज़े खोले जाएंगें और वह बेहश्त ही में दाखिल होने पाएगें यहाँ तक कि ऊँट सूई के नाके में होकर निकल जाए (यानि जिस तरह ये मुहाल है) उसी तरह उनका बेहश्त में दाखिल होना मुहाल है और हम मुजरिमों को ऐसी ही सज़ा दिया करते हैं उनके लिए जहन्नुम (की आग) का बिछौना होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,41,'Al-A''raaf','لَهُم مِّن جَهَنَّمَ مِهَادࣱ وَمِن فَوۡقِهِمۡ غَوَاشࣲۚ وَكَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ','ایسے لوگوں کے لیے (نیچے) بچھونا بھی (آتش) جہنم کا ہوگا اور اوپر سے اوڑھنا بھی (اسی کا) اور ظالموں کو ہم ایسی ہی سزا دیا کرتے ہیں','Hell will be their bed; flames will be their cover. This is how We reward the wrongdoers','और उनके ऊपर से (आग ही का) ओढ़ना भी और हम ज़ालिमों को ऐसी ही सज़ा देते हैं और जिन लोगों ने ईमान कुबुल किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,42,'Al-A''raaf','وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَآ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ','اور جو لوگ ایمان لائے اور عمل نیک کرتے رہے اور ہم (عملوں کے لیے) کسی شخص کو اس کی طاقت سے زیادہ تکلیف نہیں دیتے۔ ایسے ہی لوگ اہل بہشت ہیں (کہ) اس میں ہمیشہ رہیں گے','As for those who believe and do good—We never require of any soul more than what it can afford—it is they who will be the residents of Paradise. They will be there forever','और अच्छे अच्छे काम किये और हम तो किसी शख्स को उसकी ताकत से ज्यादा तकलीफ देते ही नहीं यहीं लोग जन्नती हैं कि वह हमेशा जन्नत ही में रहा (सहा) करेगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,43,'Al-A''raaf','وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلࣲّ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُۖ وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ لَقَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّۖ وَنُودُوٓاْ أَن تِلۡكُمُ ٱلۡجَنَّةُ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ','اور جو کینے ان کے دلوں میں ہوں گے ہم سب نکال ڈالیں گے۔ ان کے محلوں کے نیچے نہریں بہہ رہی ہوں گی اور کہیں گے کہ خدا کا شکر ہے جس نے ہم کو یہاں کا راستہ دکھایا اور اگر خدا ہم کو رستہ نہ دکھاتا تو ہم رستہ نہ پا سکتے۔ بےشک ہمارا پروردگار کے رسول حق بات لے کر آئے تھے اور (اس روز) منادی کر دی جائے گی کہ تم ان اعمال کے صلے میں جو دنیا میں کرتے تھے اس بہشت کے وارث بنا دیئے گئے ہو','We will remove whatever bitterness they had in their hearts. Rivers will flow under their feet. And they will say, “Praise be to Allah for guiding us to this. We would have never been guided if Allah had not guided us. The messengers of our Lord had certainly come with the truth.” It will be announced to them, “This is Paradise awarded to you for what you used to do.”','और उन लोगों के दिल में जो कुछ (बुग़ज़ व कीना) होगा वह सब हम निकाल (बाहर कर) देगें उनके महलों के नीचे नहरें जारी होगीं और कहते होगें शुक्र है उस ख़ुदा का जिसने हमें इस (मंज़िले मक़सूद) तक पहुंचाया और अगर ख़ुदा हमें यहाँ न पहुंचाता तो हम किसी तरह यहाँ न पहुंच सकते बेशक हमारे परवरदिगार के पैग़म्बर दीने हक़ लेकर आये थे और उन लोगों से पुकार कर कह दिया जाएगा कि वह बेहिश्त हैं जिसके तुम अपनी कारग़ुज़ारियों की जज़ा में वारिस व मालिक बनाए गये हों');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,44,'Al-A''raaf','وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡجَنَّةِ أَصۡحَٰبَ ٱلنَّارِ أَن قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقࣰّ ا فَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقࣰّ اۖ قَالُواْ نَعَمۡۚ فَأَذَّنَ مُؤَذِّنُۢ بَيۡنَهُمۡ أَن لَّعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ','اور اہل بہشت دوزخیوں سے پکار کر کہیں گے کہ جو وعدہ ہمارے پروردگار نے ہم سے کیا تھا ہم نے تو اسے سچا پالیا۔ بھلا جو وعدہ تمہارے پروردگار نے تم سے کیا تھا تم نے بھی اسے سچا پایا؟ وہ کہیں گے ہاں تو (اس وقت) ان میں ایک پکارنے والا پکارے گا کہ بےانصافوں پر خدا کی لعنت','The residents of Paradise will call out to the residents of the Fire, “We have certainly found our Lord’s promise to be true. Have you too found your Lord’s promise to be true?” They will reply, “Yes, we have!” Then a caller will announce to both, “May Allah’s condemnation be upon the wrongdoers','और जन्नती लोग जहन्नुमी वालों से पुकार कर कहेगें हमने तो बेशक जो हमारे परवरदिगार ने हमसे वायदा किया था ठीक ठीक पा लिया तो क्या तुमने भी जो तुमसे तम्हारे परवरदिगार ने वायदा किया था ठीक पाया (या नहीं) अहले जहन्नुम कहेगें हाँ (पाया) एक मुनादी उनके दरमियान निदा करेगा कि ज़ालिमों पर ख़ुदा की लानत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,45,'Al-A''raaf','ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجࣰ ا وَهُم بِٱلۡأٓخِرَةِ كَٰفِرُونَ','جو خدا کی راہ سے روکتے اور اس میں کجی ڈھونڈتے اور آخرت سے انکار کرتے تھے','those who hindered ˹others˺ from Allah’s Way, strived to make it ˹appear˺ crooked, and disbelieved in the Hereafter.”','जो ख़ुदा की राह से लोगों को रोकते थे और उसमें (ख्वामख्वाह) कज़ी (टेढ़ापन) करना चाहते थे और वह रोज़े आख़ेरत से इन्कार करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,46,'Al-A''raaf','وَبَيۡنَهُمَا حِجَابࣱۚ وَعَلَى ٱلۡأَعۡرَافِ رِجَالࣱ يَعۡرِفُونَ كُلَّۢا بِسِيمَىٰهُمۡۚ وَنَادَوۡاْ أَصۡحَٰبَ ٱلۡجَنَّةِ أَن سَلَٰمٌ عَلَيۡكُمۡۚ لَمۡ يَدۡخُلُوهَا وَهُمۡ يَطۡمَعُونَ','ان دونوں (یعنی بہشت اور دوزخ) کے درمیان (اعراف نام) ایک دیوار ہو گی اور اعراف پر کچھ آدمی ہوں گے جو سب کو ان کی صورتوں سے پہچان لیں گے۔ تو وہ اہل بہشت کو پکار کر کہیں گے کہ تم پر سلامتی ہو۔ یہ لوگ بھی بہشت میں داخل تو نہیں ہوں گے مگر امید رکھتے ہوں گے','There will be a barrier between Paradise and Hell. And on the heights ˹of that barrier˺ will be people who will recognize ˹the residents of˺ both by their appearance. They will call out to the residents of Paradise, “Peace be upon you!” They will have not yet entered Paradise, but eagerly hope to','और बेहश्त व दोज़ख के दरमियान एक हद फ़ासिल है और कुछ लोग आराफ़ पर होगें जो हर शख्स को (बेहिश्ती हो या जहन्नुमी) उनकी पेशानी से पहचान लेगें और वह जन्नत वालों को आवाज़ देगें कि तुम पर सलाम हो या (आराफ़ वाले) लोग अभी दाख़िले जन्नत नहीं हुए हैं मगर वह तमन्ना ज़रूर रखते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,47,'Al-A''raaf','۞وَإِذَا صُرِفَتۡ أَبۡصَٰرُهُمۡ تِلۡقَآءَ أَصۡحَٰبِ ٱلنَّارِ قَالُواْ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ','اور جب ان کی نگاہیں پلٹ کر اہل دوزخ کی طرف جائیں گی تو عرض کریں گے کہ اے ہمارے پروردگار ہم کو ظالم لوگوں کے ساتھ شامل نہ کیجیو','When their eyes will turn towards the residents of Hell, they will pray, “Our Lord! Do not join us with the wrongdoing people.”','और जब उनकी निगाहें पलटकर जहन्नुमी लोगों की तरफ जा पड़ेगीं (तो उनकी ख़राब हालत देखकर ख़ुदा से अर्ज़ करेगें) ऐ हमारे परवरदिगार हमें ज़ालिम लोगों का साथी न बनाना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,48,'Al-A''raaf','وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡأَعۡرَافِ رِجَالࣰ ا يَعۡرِفُونَهُم بِسِيمَىٰهُمۡ قَالُواْ مَآ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ','اور اہل اعراف (کافر) لوگوں کو جنہیں ان کی صورتوں سے شناخت کرتے ہوں گے پکاریں گے اور کہیں گے (کہ آج) نہ تو تمہاری جماعت ہی تمہارے کچھ کام آئی اور نہ تمہارا تکبّر (ہی سودمند ہوا)','Those on the heights will call out to some ˹tyrants in the Fire˺, who they will recognize by their appearance, saying, “Your large numbers and arrogance are of no use ˹today˺','और आराफ वाले कुछ (जहन्नुमी) लोगों को जिन्हें उनका चेहरा देखकर पहचान लेगें आवाज़ देगें और और कहेगें अब न तो तुम्हारा जत्था ही तुम्हारे काम आया और न तुम्हारी शेखी बाज़ी ही (सूद मन्द हुई)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,49,'Al-A''raaf','أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمۡتُمۡ لَا يَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍۚ ٱدۡخُلُواْ ٱلۡجَنَّةَ لَا خَوۡفٌ عَلَيۡكُمۡ وَلَآ أَنتُمۡ تَحۡزَنُونَ','(پھر مومنوں کی طرف اشارہ کر کے کہیں گے) کیا یہ وہی لوگ ہیں جن کے بارے میں تم قسمیں کھایا کرتے تھے کہ خدا اپنی رحمت سے ان کی دستگیری نہیں کرے گا (تو مومنو) تم بہشت میں داخل ہو جاؤ تمہیں کچھ خوف نہیں اور نہ تم کو کچھ رنج واندوہ ہوگا','Are these ˹humble believers˺ the ones you swore would never be shown Allah’s mercy?” ˹Finally, those on the heights will be told:˺ “Enter Paradise! There will be no fear for you, nor will you grieve.”','जो तुम दुनिया में किया करते थे यही लोग वह हैं जिनकी निस्बत तुम कसमें खाया करते थे कि उन पर ख़ुदा (अपनी) रहमत न करेगा (देखो आज वही लोग हैं जिनसे कहा गया कि बेतकल्लुफ) बेहश्त में चलो जाओ न तुम पर कोई खौफ है और न तुम किसी तरह आर्ज़ुदा ख़ातिर परेशानी होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,50,'Al-A''raaf','وَنَادَىٰٓ أَصۡحَٰبُ ٱلنَّارِ أَصۡحَٰبَ ٱلۡجَنَّةِ أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوٓاْ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَٰفِرِينَ','اور وہ دوزخی بہشتیوں سے (گڑگڑا کر) کہیں گے کہ کسی قدر ہم پر پانی بہاؤ یا جو رزق خدا نے تمہیں عنایت فرمایا ہے ان میں سے (کچھ ہمیں بھی دو) وہ جواب دیں گے کہ خدا نے بہشت کا پانی اور رزق کافروں پر حرام کر دیا ہے','The residents of the Fire will then cry out to the residents of Paradise, “Aid us with some water or any provision Allah has granted you.” They will reply, “Allah has forbidden both to the disbelievers','और दोज़ख वाले अहले बेहिश्त को (लजाजत से) आवाज़ देगें कि हम पर थोड़ा सा पानी ही उंडेल दो या जो (नेअमतों) खुदा ने तुम्हें दी है उसमें से कुछ (दे डालो दो तो अहले बेहिश्त जवाब में) कहेंगें कि ख़ुदा ने तो जन्नत का खाना पानी काफिरों पर कतई हराम कर दिया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,51,'Al-A''raaf','ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَهۡوࣰ ا وَلَعِبࣰ ا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ نَنسَىٰهُمۡ كَمَا نَسُواْ لِقَآءَ يَوۡمِهِمۡ هَٰذَا وَمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ','جنہوں نے اپنے دین کو تماشا اور کھیل بنا رکھا تھا اور دنیا کی زندگی نے ان کو دھوکے میں ڈال رکھا تھا۔ تو جس طرح یہ لوگ اس دن کے آنے کو بھولے ہوئے اور ہماری آیتوں سے منکر ہو رہے تھے۔ اسی طرح آج ہم بھی انہیں بھلا دیں گے','those who took this faith ˹of Islam˺ as mere amusement and play and were deluded by ˹their˺ worldly life.” ˹Allah will say,˺ “Today We will ignore them just as they ignored the coming of this Day of theirs and for rejecting Our revelations.”','जिन लोगों ने अपने दीन को खेल तमाशा बना लिया था और दुनिया की (चन्द रोज़ा) ज़िन्दगी ने उनको फरेब दिया था तो हम भी आज (क़यामत में) उन्हें (क़सदन) भूल जाएगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,52,'Al-A''raaf','وَلَقَدۡ جِئۡنَٰهُم بِكِتَٰبࣲ فَصَّلۡنَٰهُ عَلَىٰ عِلۡمٍ هُدࣰ ى وَرَحۡمَةࣰ لِّقَوۡمࣲ يُؤۡمِنُونَ','اور ہم نے ان کے پاس کتاب پہنچا دی ہے جس کو علم ودانش کے ساتھ کھول کھول کر بیان کر دیا ہے (اور) وہ مومن لوگوں کے لیے ہدایت اور رحمت ہے','We have certainly brought them a Book which We explained with knowledge—a guide and mercy for those who believe','जिस तरह यह लोग (हमारी) आज की हुज़ूरी को भूलें बैठे थे और हमारी आयतों से इन्कार करते थे हालांकि हमने उनके पास (रसूल की मारफत किताब भी भेज दी है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,53,'Al-A''raaf','هَلۡ يَنظُرُونَ إِلَّا تَأۡوِيلَهُۥۚ يَوۡمَ يَأۡتِي تَأۡوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبۡلُ قَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشۡفَعُواْ لَنَآ أَوۡ نُرَدُّ فَنَعۡمَلَ غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ قَدۡ خَسِرُوٓاْ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ','کیا یہ لوگ اس کے وعدہٴ عذاب کے منتظر ہیں۔ جس دن وہ وعدہ آجائے گا تو جو لوگ اس کو پہلے سے بھولے ہوئے ہوں گے وہ بول اٹھیں گے کہ بےشک ہمارے پروردگار کے رسول حق لے کر آئے تھے۔ بھلا (آج) ہمارا کوئی سفارشی ہیں کہ ہماری سفارش کریں یا ہم (دنیا میں) پھر لوٹا دیئے جائیں کہ جو عمل (بد) ہم (پہلے) کرتے تھے (وہ نہ کریں بلکہ) ان کے سوا اور (نیک) عمل کریں۔ بےشک ان لوگوں نے اپنا نقصان کیا اور جو کچھ یہ افتراء کیا کرتے تھے ان سے سب جاتا رہا','Do they only await the fulfilment ˹of its warning˺? The Day it will be fulfilled, those who ignored it before will say, “The messengers of our Lord certainly came with the truth. Are there any intercessors who can plead on our behalf? Or can we be sent back so we may do ˹good,˺ unlike what we used to do?” They will have certainly ruined themselves, and whatever ˹gods˺ they fabricated will fail them','जिसे हर तरह समझ बूझ के तफसीलदार बयान कर दिया है (और वह) ईमानदार लोगों के लिए हिदायत और रहमत है क्या ये लोग बस सिर्फ अन्जाम (क़यामत ही) के मुन्तज़िर है (हालांकि) जिस दिन उसके अन्जाम का (वक्त) आ जाएगा तो जो लोग उसके पहले भूले बैठे थे (बेसाख्ता) बोल उठेगें कि बेशक हमारे परवरदिगार के सब रसूल हक़ लेकर आये थे तो क्या उस वक्त हमारी भी सिफरिश करने वाले हैं जो हमारी सिफारिश करें या हम फिर (दुनिया में) लौटाएं जाएं तो जो जो काम हम करते थे उसको छोड़कर दूसरें काम करें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,54,'Al-A''raaf','إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَ يَطۡلُبُهُۥ حَثِيثࣰ ا وَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتِۭ بِأَمۡرِهِۦٓۗ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ','کچھ شک نہیں کہ تمہارا پروردگار خدا ہی ہے جس نے آسمانوں اور زمین کو چھ دن میں پیدا کیا پھر عرش پر جا ٹھہرا۔ وہی رات کو دن کا لباس پہناتا ہے کہ وہ اس کے پیچھے دوڑتا چلا آتا ہے۔ اور اسی نے سورج اور چاند ستاروں کو پیدا کیا سب اس کے حکم کے مطابق کام میں لگے ہوئے ہیں۔ دیکھو سب مخلوق بھی اسی کی ہے اور حکم بھی (اسی کا ہے) ۔ یہ خدا رب العالمین بڑی برکت والا ہے','Indeed your Lord is Allah Who created the heavens and the earth in six Days, then established Himself on the Throne. He makes the day and night overlap in rapid succession. He created the sun, the moon, and the stars—all subjected by His command. The creation and the command belong to Him ˹alone˺. Blessed is Allah—Lord of all worlds','बेशक उन लोगों ने अपना सख्त घाटा किया और जो इफ़तेरा परदाज़िया किया करते थे वह सब गायब (ग़ल्ला) हो गयीं बेशक तुम्हारा परवरदिगार ख़ुदा ही है जिसके (सिर्फ) 6 दिनों में आसमान और ज़मीन को पैदा किया फिर अर्श के बनाने पर आमादा हुआ वही रात को दिन का लिबास पहनाता है तो (गोया) रात दिन को पीछे पीछे तेज़ी से ढूंढती फिरती है और उसी ने आफ़ताब और माहताब और सितारों को पैदा किया कि ये सब के सब उसी के हुक्म के ताबेदार हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,55,'Al-A''raaf','ٱدۡعُواْ رَبَّكُمۡ تَضَرُّعࣰ ا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ','(لوگو) اپنے پروردگار سے عاجزی سے اور چپکے چپکے دعائیں مانگا کرو۔ وہ حد سے بڑھنے والوں کو دوست نہیں رکھتا','Call upon your Lord humbly and secretly. Surely He does not like the transgressors','देखो हुकूमत और पैदा करना बस ख़ास उसी के लिए है वह ख़ुदा जो सारे जहाँन का परवरदिगार बरक़त वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,56,'Al-A''raaf','وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا وَٱدۡعُوهُ خَوۡفࣰ ا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبࣱ مِّنَ ٱلۡمُحۡسِنِينَ','اور ملک میں اصلاح کے بعد خرابی نہ کرنا اور خدا سے خوف کرتے ہوئے اور امید رکھ کر دعائیں مانگتے رہنا۔ کچھ شک نہیں کہ خدا کی رحمت نیکی کرنے والوں سے قریب ہے','Do not spread corruption in the land after it has been set in order. And call upon Him with hope and fear. Indeed, Allah’s mercy is always close to the good-doers','(लोगों) अपने परवरदिगार से गिड़गिड़ाकर और चुपके - चुपके दुआ करो, वह हद से तजाविज़ करने वालों को हरगिज़ दोस्त नहीं रखता और ज़मीन में असलाह के बाद फसाद न करते फिरो और (अज़ाब) के ख़ौफ से और (रहमत) की आस लगा के ख़ुदा से दुआ मांगो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,57,'Al-A''raaf','وَهُوَ ٱلَّذِي يُرۡسِلُ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۖ حَتَّىٰٓ إِذَآ أَقَلَّتۡ سَحَابࣰ ا ثِقَالࣰ ا سُقۡنَٰهُ لِبَلَدࣲ مَّيِّتࣲ فَأَنزَلۡنَا بِهِ ٱلۡمَآءَ فَأَخۡرَجۡنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِۚ كَذَٰلِكَ نُخۡرِجُ ٱلۡمَوۡتَىٰ لَعَلَّكُمۡ تَذَكَّرُونَ','اور وہی تو ہے جو اپنی رحمت (یعنی مینھ) سے پہلے ہواؤں کو خوشخبری (بنا کر) بھیجتا ہے۔ یہاں تک کہ جب وہ بھاری بھاری بادلوں کو اٹھا لاتی ہے تو ہم اس کو ایک مری ہوئی بستی کی طرف ہانک دیتے ہیں۔ پھر بادل سے مینھ برساتے ہیں۔ پھر مینھ سے ہر طرح کے پھل پیدا کرتے ہیں۔ اسی طرح ہم مردوں کو (زمین سے) زندہ کرکے باہر نکال لیں گے۔ (یہ آیات اس لیے بیان کی جاتی ہیں) تاکہ تم نصیحت پکڑو','He is the One Who sends the winds ushering in His mercy. When they bear heavy clouds, We drive them to a lifeless land and then cause rain to fall, producing every type of fruit. Similarly, We will bring the dead to life, so perhaps you will be mindful','(क्योंकि) नेकी करने वालों से ख़ुदा की रहमत यक़ीनन क़रीब है और वही तो (वह) ख़ुदा है जो अपनी रहमत (अब्र) से पहले खुशखबरी देने वाली हवाओ को भेजता है यहाँ तक कि जब हवाएं (पानी से भरे) बोझल बादलों के ले उड़े तो हम उनको किसी शहर की की तरफ (जो पानी का नायाबी (कमी) से गोया) मर चुका था हॅका दिया फिर हमने उससे पानी बरसाया, फिर हमने उससे हर तरह के फल ज़मीन से निकाले');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,58,'Al-A''raaf','وَٱلۡبَلَدُ ٱلطَّيِّبُ يَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ وَٱلَّذِي خَبُثَ لَا يَخۡرُجُ إِلَّا نَكِدࣰ اۚ كَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ لِقَوۡمࣲ يَشۡكُرُونَ','جو زمین پاکیزہ (ہے) اس میں سے سبزہ بھی پروردگار کے حکم سے (نفیس ہی) نکلتا ہے اور جو خراب ہے اس میں جو کچھ ہے ناقص ہوتا ہے۔ اسی طرح ہم آیتوں کو شکرگزار لوگوں کے لئے پھیر پھیر کر بیان کرتے ہیں','The fertile land produces abundantly by the Will of its Lord, whereas the infertile land hardly produces anything. This is how We vary ˹Our˺ lessons to those who are thankful','हम यूं ही (क़यामत के दिन ज़मीन से) मुर्दों को निकालेंगें ताकि तुम लोग नसीहत व इबरत हासिल करो और उम्दा ज़मीन उसके परवरदिगार के हुक्म से उस सब्ज़ा (अच्छा ही) है और जो ज़मीन बड़ी है उसकी पैदावार ख़राब ही होती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,59,'Al-A''raaf','لَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمࣲ‏','ہم نے نوح کو ان کی قوم کی طرف بھیجا تو انہوں نے (ان سے کہا) اے میری برادری کے لوگو خدا کی عبادت کرو اس کے سوا تمہارا کوئی معبود نہیں۔ مجھے تمہارے بارے میں بڑے دن کے عذاب کا (بہت ہی) ڈر ہے','Indeed, We sent Noah to his people. He said, “O my people! Worship Allah—you have no other god except Him. I truly fear for you the torment of a tremendous Day.”','हम यू अपनी आयतों को उलेटफेर कर शुक्रग़ुजार लोगों के वास्ते बयान करते हैं बेशक हमने नूह को उनकी क़ौम के पास (रसूल बनाकर) भेजा तो उन्होनें (लोगों से ) कहाकि ऐ मेरी क़ौम ख़ुदा की ही इबादत करो उसके सिवा तुम्हारा कोई माबूद नहीं है और मैं तुम्हारी निस्बत (क़यामत जैसे) बड़े ख़ौफनाक दिन के अज़ाब से डरता हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,60,'Al-A''raaf','قَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي ضَلَٰلࣲ مُّبِينࣲ‏','تو جو ان کی قوم میں سردار تھے وہ کہنے لگے کہ ہم تمہیں صریح گمراہی میں (مبتلا) دیکھتے ہیں','But the chiefs of his people said, “We surely see that you are clearly misguided.”','तो उनकी क़ौम के चन्द सरदारों ने कहा हम तो यक़ीनन देखते हैं कि तुम खुल्लम खुल्ला गुमराही में (पड़े) हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,61,'Al-A''raaf','قَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةࣱ وَلَٰكِنِّي رَسُولࣱ مِّن رَّبِّ ٱلۡعَٰلَمِينَ','انہوں نے کہا اے قوم مجھ میں کسی طرح کی گمراہی نہیں ہے بلکہ میں پروردگار عالم کا پیغمبر ہوں','He replied, “O my people! I am not misguided! But I am a messenger from the Lord of all worlds','तब नूह ने कहा कि ऐ मेरी क़ौम मुझ में गुमराही (वग़ैरह) तो कुछ नहीं बल्कि मैं तो परवरदिगारे आलम की तरफ से रसूल हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,62,'Al-A''raaf','أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ','تمہیں اپنے پروردگار کے پیغام پہنچاتا ہوں اور تمہاری خیرخواہی کرتا ہوں اور مجھ کو خدا کی طرف سے ایسی باتیں معلوم ہیں جن سے تم بےخبر ہو','conveying to you my Lord’s messages and giving you ˹sincere˺ advice. And I know from Allah what you do not know','तुम तक अपने परवरदिगार के पैग़ामात पहुचाएं देता हूँ और तुम्हारे लिए तुम्हारी ख़ैर ख्वाही करता हूँ और ख़ुदा की तरफ से जो बातें मै जानता हूँ तुम नहीं जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,63,'Al-A''raaf','أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرࣱ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلࣲ مِّنكُمۡ لِيُنذِرَكُمۡ وَلِتَتَّقُواْ وَلَعَلَّكُمۡ تُرۡحَمُونَ','کیا تم کو اس بات سے تعجب ہوا ہے کہ تم میں سے ایک شخص کے ہاتھ تمہارے پروردگار کی طرف سے تمہارے پاس نصیحت آئی تاکہ وہ تم کو ڈرائے اور تاکہ تم پرہیزگار بنو اور تاکہ تم پر رحم کیا جائے','Do you find it astonishing that a reminder should come to you from your Lord through one of your own, warning you, so you may beware and perhaps be shown mercy?”','क्या तुम्हें उस बात पर ताअज्जुब है कि तुम्हारे पास तुम्ही में से एक मर्द (आदमी) के ज़रिए से तुम्हारे परवरदिगार का ज़िक्र (हुक्म) आया है ताकि वह तुम्हें (अज़ाब से) डराए और ताकि तुम परहेज़गार बनों और ताकि तुम पर रहम किया जाए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,64,'Al-A''raaf','فَكَذَّبُوهُ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمًا عَمِينَ','مگر ان لوگوں نے ان کی تکذیب کی۔ تو ہم نے نوح کو اور جو ان کے ساتھ کشتی میں سوار تھے ان کو تو بچا لیا اور جن لوگوں نے ہماری آیتوں کو جھٹلایا تھا انہیں غرق کر دیا۔ کچھ شک نہیں کہ وہ اندھے لوگ تھے','But they rejected him, so We saved him and those with him in the Ark, and drowned those who rejected Our signs. They were certainly a blind people','इस पर भी लोगों ने उनकों झुठला दिया तब हमने उनको और जो लोग उनके साथ कश्ती में थे बचा लिया और बाक़ी जितने लोगों ने हमारी आयतों को झुठलाया था सबको डुबो मारा ये सब के सब यक़ीनन अन्धे लोग थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,65,'Al-A''raaf','۞وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ','اور (اسی طرح) قوم عاد کی طرف ان کے بھائی ہود کو بھیجا۔ انہوں نے کہا کہ بھائیو خدا ہی کی عبادت کرو۔ اس کے سوا تمہارا کوئی معبود نہیں۔ کیا تم ڈرتے نہیں؟','And to the people of ’Âd We sent their brother Hûd. He said, “O my people! Worship Allah—you have no other god except Him. Will you not then fear Him?”','और (हमने) क़ौम आद की तरफ उनके भाई हूद को (रसूल बनाकर भेजा) तो उन्होनें लोगों से कहा ऐ मेरी क़ौम ख़ुदा ही की इबादत करो उसके सिवा तुम्हारा कोई माबूद नहीं तो क्या तुम (ख़ुदा से) डरते नहीं हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,66,'Al-A''raaf','قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي سَفَاهَةࣲ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَٰذِبِينَ','تو ان کی قوم کے سردار جو کافر تھے کہنے لگے کہ تم ہمیں احمق نظر آتے ہو اور ہم تمہیں جھوٹا خیال کرتے ہیں','The disbelieving chiefs of his people responded, “We surely see you as a fool, and we certainly think you are a liar.”','(तो) उनकी क़ौम के चन्द सरदार जो काफिर थे कहने लगे हम तो बेशक तुमको हिमाक़त में (मुब्तिला) देखते हैं और हम यक़ीनी तुम को झूठा समझते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,67,'Al-A''raaf','قَالَ يَٰقَوۡمِ لَيۡسَ بِي سَفَاهَةࣱ وَلَٰكِنِّي رَسُولࣱ مِّن رَّبِّ ٱلۡعَٰلَمِينَ','انہوں نے کہا کہ بھائیو مجھ میں حماقت کی کوئی بات نہیں ہے بلکہ میں رب العالمین کا پیغمبر ہوں','Hûd replied, “O my people! I am no fool! But I am a messenger from the Lord of all worlds','हूद ने कहा ऐ मेरी क़ौम मुझमें में तो हिमाक़त की कोई बात नहीं बल्कि मैं तो परवरदिगार आलम का रसूल हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,68,'Al-A''raaf','أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ','میں تمہیں خدا کے پیغام پہنچاتا ہوں اور تمہارا امانت دار خیرخواہ ہوں','conveying to you my Lord’s messages. And I am your sincere advisor','मैं तुम्हारे पास तुम्हारे परवरदिगार के पैग़ामात पहँचाए देता हूँ और मैं तुम्हारा सच्चा ख़ैरख्वाह हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,69,'Al-A''raaf','أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرࣱ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلࣲ مِّنكُمۡ لِيُنذِرَكُمۡۚ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحࣲ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةࣰۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ','کیا تم کو اس بات سے تعجب ہوا ہے کہ تم میں سے ایک شخص کے ہاتھ تمہارے پروردگار کی طرف سے تمہارے پاس نصیحت آئی تاکہ وہ تمہیں ڈرائے اور یاد کرو تو کرو جب اس نے تم کو قوم نوح کے بعد سردار بنایا۔ اور تم کو پھیلاؤ زیادہ دیا۔ پس خدا کی نعمتوں کو یاد کرو۔ تاکہ نجات حاصل کرو','Do you find it astonishing that a reminder should come to you from your Lord through one of your own so he may warn you? Remember that He made you successors after the people of Noah and increased you greatly in stature. So remember Allah’s favours, so you may be successful.”','क्या तुम्हें इस पर ताअज्जुब है कि तुम्हारे परवरदिगार का हुक्म तुम्हारे पास तुम्ही में एक मर्द (आदमी) के ज़रिए से (आया) कि तुम्हें (अजाब से) डराए और (वह वक्त) याद करो जब उसने तुमको क़ौम नूह के बाद ख़लीफा (व जानशीन) बनाया और तुम्हारी ख़िलाफ़त में भी बहुत ज्यादती कर दी तो ख़ुदा की नेअमतों को याद करो ताकि तुम दिली मुरादे पाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,70,'Al-A''raaf','قَالُوٓاْ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ','وہ کہنے لگے کہ تم ہمارے پاس اس لیے آئے ہو کہ ہم اکیلے خدا ہی کی عبادت کریں۔ اور جن کو ہمارے باپ دادا پوجتے چلے آئے ہیں ان کو چھوڑ دیں؟ تو اگر سچے ہو تو جس چیز سے ہمیں ڈراتے ہو اسے لے آؤ','They said, “Have you come to us so that we would worship Allah alone and abandon what our forefathers used to worship? Then bring us what you threaten us with, if what you say is true!”','तो वह लोग कहने लगे क्या तुम हमारे पास इसलिए आए हो कि सिर्फ ख़ुदा की तो इबादत करें और जिनको हमारे बाप दादा पूजते चले आए छोड़ बैठें पस अगर तुम सच्चे हो तो जिससे तुम हमको डराते हो हमारे पास लाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,71,'Al-A''raaf','قَالَ قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسࣱ وَغَضَبٌۖ أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءࣲ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنࣲۚ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ','ہود نے کہا تمہارے پروردگار کی طرف سے تم پر عذاب اور غضب کا (نازل ہونا) مقرر ہو چکا ہے۔ کیا تم مجھ سے ایسے ناموں کے بارے میں جھگڑتے ہو جو تم نے اور تمہارے باپ دادا نے (اپنی طرف سے) رکھ لئے ہیں۔ جن کی خدا نے کوئی سند نازل نہیں کی۔ تو تم بھی انتظار کرو میں بھی تمہارے ساتھ انتظار کرتا ہوں','He said, “You will certainly be subjected to your Lord’s torment and wrath. Do you dispute with me regarding the so-called gods which you and your forefathers have made up—a practice Allah has never authorized? Then wait! I too am waiting with you.”','हूद ने जवाब दिया (कि बस समझ लो) कि तुम्हारे परवरदिगार की तरफ से तुम पर अज़ाब और ग़ज़ब नाज़िल हो चुका क्या तुम मुझसे चन्द (बुतो के फर्ज़ी) नामों के बारे में झगड़ते हो जिनको तुमने और तुम्हारे बाप दादाओं ने (ख्वाहमख्वाह) गढ़ लिए हैं हालाकि ख़ुदा ने उनके लिए कोई सनद नहीं नाज़िल की पस तुम ( अज़ाबे ख़ुदा का) इन्तज़ार करो मैं भी तुम्हारे साथ मुन्तिज़र हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,72,'Al-A''raaf','فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَقَطَعۡنَا دَابِرَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ وَمَا كَانُواْ مُؤۡمِنِينَ','پھر ہم نے ہود کو اور جو لوگ ان کے ساتھ تھے ان کو نجات بخشی اور جنہوں نے ہماری آیتوں کو جھٹلایا تھا ان کی جڑ کاٹ دی اور وہ ایمان لانے والے تھے ہی نہیں','So We saved him and those with him by Our mercy and uprooted those who denied Our signs. They were not believers','आख़िर हमने उनको और जो लोग उनके साथ थे उनको अपनी रहमत से नजात दी और जिन लोगों ने हमारी आयतों को झुठलाया था हमने उनकी जड़ काट दी और वह लोग ईमान लाने वाले थे भी नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,73,'Al-A''raaf','وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحࣰ اۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةࣱ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةࣰۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءࣲ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمࣱ‏','اور قوم ثمود کی طرف ان کے بھائی صالح کو بھیجا۔ (تو) صالح نے کہا کہ اے قوم! خدا ہی کی عبادت کرو اس کے سوا تمہارا کوئی معبود نہیں۔ تمہارے پاس تمہارے پروردگار کی طرف سے ایک معجزہ آ چکا ہے۔ (یعنی) یہی خدا کی اونٹنی تمہارے لیے معجزہ ہے۔ تو اسے (آزاد) چھوڑ دو کہ خدا کی زمین میں چرتی پھرے اور تم اسے بری نیت سے ہاتھ بھی نہ لگانا۔ ورنہ عذابِ الیم میں تمہیں پکڑ لے گا','And to the people of Thamûd We sent their brother Ṣâliḥ. He said, “O my people! Worship Allah—you have no other god except Him. A clear proof has come to you from your Lord: this is Allah’s she-camel as a sign to you. So leave her to graze ˹freely˺ on Allah’s land and do not harm her, or else you will be overcome by a painful punishment','और (हमने क़ौम) समूद की तरफ उनके भाई सालेह को रसूल बनाकर भेजा तो उन्होनें (उन लोगों से कहा) ऐ मेरी क़ौम ख़ुदा ही की इबादत करो और उसके सिवा कोई तुम्हारा माबूद नहीं है तुम्हारे पास तो तुम्हारे परवरदिगार की तरफ से वाज़ेए और रौशन दलील आ चुकी है ये ख़ुदा की भेजी हुई ऊँटनी तुम्हारे वास्ते एक मौजिज़ा है तो तुम लोग उसको छोड़ दो कि ख़ुदा की ज़मीन में जहाँ चाहे चरती फिरे और उसे कोई तकलीफ़ ना पहुंचाओ वरना तुम दर्दनाक अज़ाब में गिरफ्तार हो जाआगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,74,'Al-A''raaf','وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادࣲ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورࣰ ا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتࣰ اۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ','اور یاد تو کرو جب اس نے تم کو قوم عاد کے بعد سردار بنایا اور زمین پر آباد کیا کہ نرم زمین سے (مٹی لے لے کر) محل تعمیر کرتے ہو اور پہاڑوں کو تراش تراش کر گھر بناتے ہو۔ پس خدا کی نعمتوں کو یاد کرو اور زمین میں فساد نہ کرتے پھرو','Remember when He made you successors after ’Âd and established you in the land—˹and˺ you built palaces on its plains and carved homes into mountains. So remember Allah’s favours, and do not go about spreading corruption in the land.”','और वह वक्त याद करो जब उसने तुमको क़ौम आद के बाद (ज़मीन में) ख़लीफा (व जानशीन) बनाया और तुम्हें ज़मीन में इस तरह बसाया कि तुम हमवार व नरम ज़मीन में (बड़े-बड़े) महल उठाते हो और पहाड़ों को तराश के घर बनाते हो तो ख़ुदा की नेअमतों को याद करो और रूए ज़मीन में फसाद न करते फिरो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,75,'Al-A''raaf','قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لِلَّذِينَ ٱسۡتُضۡعِفُواْ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَٰلِحࣰ ا مُّرۡسَلࣱ مِّن رَّبِّهِۦۚ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ','تو ان کی قوم میں سردار لوگ جو غرور رکھتے تھے غریب لوگوں سے جو ان میں سے ایمان لے آئے تھے کہنے لگے بھلا تم یقین کرتے ہو کہ صالح اپنے پروردگار کی طرف بھیجے گئے ہیں؟ انہوں نے کہا ہاں جو چیز دے کر وہ بھیجے گئے ہیں ہم اس پر بلاشبہ ایمان رکھتے ہیں','The arrogant chiefs of his people asked the lowly who believed among them, “Are you certain that Ṣâliḥ has been sent by his Lord?” They replied, “We certainly believe in what he has been sent with.”','तो उसकी क़ौम के बड़े बड़े लोगों ने बेचारें ग़रीबों से उनमें से जो ईमान लाए थे कहा क्या तुम्हें मालूम है कि सालेह (हक़ीकतन) अपने परवरदिगार के सच्चे रसूल हैं - उन बेचारों ने जवाब दिया कि जिन बातों का वह पैग़ाम लाए हैं हमारा तो उस पर ईमान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,76,'Al-A''raaf','قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا بِٱلَّذِيٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ','تو (سرداران) مغرور کہنے لگے کہ جس چیز پر تم ایمان لائے ہو ہم تو اس کو نہیں مانتے','The arrogant said, “We surely reject what you believe in.”','तब जिन लोगों को (अपनी दौलत दुनिया पर) घमन्ड था कहने लगे हम तो जिस पर तुम ईमान लाए हो उसे नहीं मानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,77,'Al-A''raaf','فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ','آخر انہوں نے اونٹی (کی کونچوں) کو کاٹ ڈالا اور اپنے پروردگار کے حکم سے سرکشی کی اور کہنے لگے کہ صالح! جس چیز سے تم ہمیں ڈراتے تھے اگر تم (خدا کے) پیغمبر ہو تو اسے ہم پر لے آؤ','Then they killed the she-camel—defying their Lord’s command—and challenged ˹Ṣâliḥ˺, “Bring us what you threaten us with, if you are ˹truly˺ one of the messengers.”','ग़रज़ उन लोगों ने ऊँटनी के कूचें और पैर काट डाले और अपने परवरदिगार के हुक्म से सरताबी की और (बेबाकी से) कहने लगे अगर तुम सच्चे रसूल हो तो जिस (अज़ाब) से हम लोगों को डराते थे अब लाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,78,'Al-A''raaf','فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ','تو ان کو بھونچال نے آ پکڑا اور وہ اپنے گھروں میں اوندھے پڑے رہ گئے','Then an ˹overwhelming˺ earthquake struck them, and they fell lifeless in their homes','तब उन्हें ज़लज़ले ने ले डाला और वह लोग ज़ानू पर सर किए (जिस तरह) बैठे थे बैठे के बैठे रह गए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,79,'Al-A''raaf','فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ','پھر صالح ان سے (ناامید ہو کر) پھرے اور کہا کہ میری قوم! میں نے تم کو خدا کا پیغام پہنچا دیا اور تمہاری خیر خواہی کی مگر تم (ایسے ہو کہ) خیر خواہوں کو دوست ہی نہیں رکھتے','So he turned away from them, saying, “O my people! Surely I conveyed to you my Lord’s message and gave you ˹sincere˺ advice, but you do not like ˹sincere˺ advisors.”','उसके बाद सालेह उनसे टल गए और (उनसे मुख़ातिब होकर) कहा मेरी क़ौम (आह) मैनें तो अपने परवरदिगार के पैग़ाम तुम तक पहुचा दिए थे और तुम्हारे ख़ैरख्वाही की थी (और ऊँच नीच समझा दिया था) मगर अफसोस तुम (ख़ैरख्वाह) समझाने वालों को अपना दोस्त ही नहीं समझते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,80,'Al-A''raaf','وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدࣲ مِّنَ ٱلۡعَٰلَمِينَ','اور اسی طرح جب ہم نے لوط کو (پیغمبر بنا کر بھیجا تو) اس وقت انہوں نے اپنی قوم سے کہا کہ تم ایسی بےحیائی کا کام کیوں کرتے ہو کہ تم سے اہل عالم میں سے کسی نے اس طرح کا کام نہیں کیا','And ˹remember˺ when Lot scolded ˹the men of˺ his people, ˹saying,˺ “Do you commit a shameful deed that no man has ever done before','और (लूत को हमने रसूल बनाकर भेजा था) जब उन्होनें अपनी क़ौम से कहा कि (अफसोस) तुम ऐसी बदकारी (अग़लाम) करते हो कि तुमसे पहले सारी ख़ुदाई में किसी ने ऐसी बदकारी नहीं की थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,81,'Al-A''raaf','إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةࣰ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمࣱ مُّسۡرِفُونَ','یعنی خواہش نفسانی پورا کرنے کے لیے عورتوں کو چھوڑ کر لونڈوں پر گرتے ہو۔ حقیقت یہ ہے کہ تم لوگ حد سے نکل جانے والے ہو','You lust after men instead of women! You are certainly transgressors.”','हाँ तुम औरतों को छोड़कर शहवत परस्ती के वास्ते मर्दों की तरफ माएल होते हो (हालाकि उसकी ज़रूरत नहीं) मगर तुम लोग कुछ हो ही बेहूदा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,82,'Al-A''raaf','وَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسࣱ يَتَطَهَّرُونَ','تو ان سے اس کا جواب کچھ نہ بن پڑا اور بولے تو یہ بولے کہ ان لوگوں (یعنی لوط اور اس کے گھر والوں) کو اپنے گاؤں سے نکال دو (کہ) یہ لوگ پاک بننا چاہتے ہیں','But his people’s only response was to say, “Expel them from your land! They are a people who wish to remain chaste!”','सिर्फ करनें वालों (को नुत्फे को ज़ाए करते हो उस पर उसकी क़ौम का उसके सिवा और कुछ जवाब नहीं था कि वह आपस में कहने लगे कि उन लोगों को अपनी बस्ती से निकाल बाहर करो क्योंकि ये तो वह लोग हैं जो पाक साफ बनना चाहते हैं)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,83,'Al-A''raaf','فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ','تو ہم نے ان کو اور ان کے گھر والوں کو بچا لیا مگر ان کی بی بی (نہ بچی) کہ وہ پیچھے رہنے والوں میں تھی','So We saved him and his family except his wife, who was one of the doomed','तब हमने उनको और उनके घर वालों को नजात दी मगर सिर्फ (एक) उनकी बीबी को कि वह (अपनी बदआमाली से) पीछे रह जाने वालों में थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (7,84,'Al-A''raaf','وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرࣰ اۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ','اور ہم نے ان پر (پتھروں کا) مینھ برسایا۔ سو دیکھ لو کہ گنہگاروں کا کیسا انجام ہوا','We poured upon them a rain ˹of brimstone˺. See what was the end of the wicked','और हमने उन लोगों पर (पत्थर का) मेह बरसाया-पस ज़रा ग़ौर तो करो कि गुनाहगारों का अन्जाम आखिर क्या हुआ');
